/**
 * 创建角色世界书条目（绿灯）
 */
export function createCharacterEntry(
  characterName: string,
  yamlContent: string,
  config: { keys: string[]; order: number },
): Partial<WorldbookEntry> {
  return {
    name: characterName,
    enabled: true,
    strategy: {
      type: 'selective', // 绿灯
      keys: config.keys,
      keys_secondary: { logic: 'and_any', keys: [] },
      scan_depth: 4, // 角色一般扫描4层
    },
    position: {
      type: 'before_character_definition', // 角色定义前
      role: 'system',
      depth: 0,
      order: config.order, // 统一顺序8
    },
    content: yamlContent, // YAML 原文
    probability: 100,
    recursion: {
      prevent_incoming: true, // 不可递归
      prevent_outgoing: true, // 防止进一步递归
      delay_until: null,
    },
    effect: {
      sticky: 3, // 角色条目激活后持续3条消息
      cooldown: null,
      delay: null,
    },
  };
}

/**
 * 加载内容到世界书条目
 */
export async function loadContentToEntries(
  entries: Partial<WorldbookEntry>[],
  contentMap: Map<string, string>,
): Promise<Partial<WorldbookEntry>[]> {
  return entries.map(entry => {
    const content = contentMap.get(entry.name!);
    if (content) {
      return { ...entry, content };
    }
    return entry;
  });
}
