import { StrictMode, useMemo, useState } from 'react';
import { createRoot, Root } from 'react-dom/client';
import { PhoneSimulator } from '../校园APP/状态栏/src/components/PhoneSimulator';
import { OpeningFlow } from '../校园APP/游戏开局/OpeningFlow';
import { FloatingPhoneHost, restoreCampusFrame } from '../校园APP/游戏开局/FloatingPhoneHost';
import { writeEnrollmentArchivesToWorldbook } from '../校园APP/游戏开局/playerArchive';
import { sendOpeningPrompt } from '../校园APP/游戏开局/openingPrompt';
import { CustomStartForm } from '../校园APP/游戏开局/constants';
import { checkCampusAppUpdate, getRuntimeInfo, setRuntimeSourceUrl } from '../校园APP/状态栏/src/utils/runtimeVersion';
import { registerCampusArraySchemaRepair } from '../校园APP/游戏开局/campusLocations';
import '../校园APP/index.css';

/**
 * 校园APP 浮窗启动脚本（独立脚本入口，不依赖消息楼层正则）
 *
 * 酒馆助手中这样导入（只能 import JS，不能 import HTML）：
 *   开发：import 'http://localhost:5501/dist/校园APP浮窗/index.js'
 *   发布：import 'https://testingcf.jsdelivr.net/gh/你的仓库@版本/dist/校园APP浮窗/index.js'
 *        或 import 'https://raw.githack.com/用户/仓库/main/校园APP浮窗/index.js'
 *
 * 注意：脚本里的 $ 指向酒馆父页面；界面应挂在脚本自身 iframe 的 document 上，
 * 绝不要 $('body').empty()，否则会把整个酒馆页面清空。
 */

setRuntimeSourceUrl(import.meta.url);

let root: Root | null = null;

function markScriptFrame() {
  const frame = window.frameElement as HTMLIFrameElement | null;
  if (!frame) return;
  frame.dataset.campusScriptMounted = '1';
  frame.setAttribute('allowtransparency', 'true');
  frame.setAttribute('title', '校园APP');
}

// 尽早标记，避免后续渲染误调 getCurrentMessageId
markScriptFrame();

function isScriptContext(): boolean {
  const frame = window.frameElement as HTMLIFrameElement | null;
  if (frame?.dataset.campusScriptMounted === '1') return true;
  return /TH-script/i.test(frame?.id || '');
}

function shouldShowOpening(enrolled: boolean): boolean {
  if (enrolled) return false;
  // 全局脚本没有消息楼层；用最新楼层号判断是否为新开局
  try {
    if (typeof getLastMessageId === 'function') {
      return getLastMessageId() <= 0;
    }
  } catch {
    // ignore
  }
  return isScriptContext();
}

function CampusApp() {
  const [enrolled, setEnrolled] = useState(false);
  const showOpening = useMemo(() => shouldShowOpening(enrolled), [enrolled]);

  const handleEnroll = async (form: CustomStartForm) => {
    const ok = await writeEnrollmentArchivesToWorldbook(form);
    if (!ok) return;
    // 活动不写入世界书：由开篇提示词交给 AI，输出 MVU「校园建筑.建筑活动」更新
    setEnrolled(true);
    await sendOpeningPrompt(form);
  };

  if (showOpening) {
    return <OpeningFlow onEnroll={form => void handleEnroll(form)} />;
  }

  return <PhoneSimulator />;
}

function prepareFrameDocument() {
  const html = document.documentElement;
  const body = document.body;
  html.style.cssText = 'width:100%;height:100%;margin:0;padding:0;overflow:hidden;background:transparent;';
  body.style.cssText = 'width:100%;height:100%;margin:0;padding:0;overflow:hidden;background:transparent;';
}

function ensureRoot(): HTMLElement {
  prepareFrameDocument();
  let rootElement = document.getElementById('root');
  if (!rootElement) {
    rootElement = document.createElement('div');
    rootElement.id = 'root';
    rootElement.style.cssText = 'width:100%;height:100%;margin:0;padding:0;overflow:hidden;background:transparent;';
    document.body.appendChild(rootElement);
  }
  return rootElement;
}

function unmountApp() {
  root?.unmount();
  root = null;
  restoreCampusFrame();
  console.info('[校园APP浮窗] 已卸载');
}

async function mountApp() {
  const runtime = getRuntimeInfo();
  console.info(`[校园APP浮窗] 渠道=${runtime.channel} 来源=${runtime.sourceKind} 版本=${runtime.version}`);
  if (runtime.sourceUrl) {
    console.info('[校园APP浮窗] 加载地址', runtime.sourceUrl);
  }
  void checkCampusAppUpdate().then(result => {
    if (result.hasUpdate) {
      console.info(`[校园APP浮窗] 发现新版本 ${result.latest?.version || ''} (${result.latest?.buildId || ''})`);
    }
  });

  console.info('[校园APP浮窗] 等待 MVU 框架初始化...');
  await waitGlobalInitialized('Mvu');
  console.info('[校园APP浮窗] MVU 框架已初始化');
  registerCampusArraySchemaRepair();

  markScriptFrame();
  const rootElement = ensureRoot();
  root?.unmount();
  root = createRoot(rootElement);
  root.render(
    <StrictMode>
      <FloatingPhoneHost>
        <CampusApp />
      </FloatingPhoneHost>
    </StrictMode>,
  );
  console.info('[校园APP浮窗] 已挂载');
}

$(() => {
  void mountApp();
});

$(window).on('pagehide', () => {
  unmountApp();
});
