import React, { useState } from 'react';
import { Character } from '../../types';
import { motion } from 'framer-motion';
import { ClothingInfo } from '../profile/ClothingInfo';
import { Heart, MapPin, MessageCircleHeart, Star, User, GraduationCap, Sparkles, ChevronsUp, ChevronLeft } from 'lucide-react';
import { ImageUpload } from './ImageUpload';
import { useDraggableScroll } from '../../hooks/useDraggableScroll';
import { Card } from '../ui/Card';
import { BottomSheetModal } from '../ui/Modal';
import { getPresetCharacterImages } from '../../utils/presetCharacterImages';

interface CharacterModalProps {
  character: Character | null;
  onClose: () => void;
  onAvatarUpload: (id: string, url: string) => void;
}

function splitTags(value?: string | string[]): string[] {
  if (Array.isArray(value)) {
    return value.map(item => String(item).trim()).filter(Boolean);
  }
  if (!value) return [];
  return value
    .split(/[,，、/|]+/)
    .map(item => item.trim())
    .filter(Boolean);
}

function TagChip({
  text,
  tone = 'pink',
}: {
  text: string;
  tone?: 'pink' | 'orange' | 'violet' | 'sky';
}) {
  const tones = {
    pink: 'soft-chip',
    orange: 'soft-chip',
    violet: 'soft-chip',
    sky: 'soft-chip',
  };
  return (
    <span className={`inline-flex items-center px-1.5 py-0.5 rounded-full text-[10px] font-bold shrink-0 ${tones[tone]}`}>
      {text}
    </span>
  );
}

export function CharacterModal({ character, onClose, onAvatarUpload }: CharacterModalProps) {
  const dragProps = useDraggableScroll<HTMLDivElement>();
  const presetImages = character ? getPresetCharacterImages(character.name, character.id) : undefined;
  const portraits = presetImages?.portraits || [];
  const [scrollTop, setScrollTop] = useState(0);
  const [portraitIndex, setPortraitIndex] = useState(() => Math.floor(Math.random() * Math.max(portraits.length, 1)));
  const [portraitStartX, setPortraitStartX] = useState<number | null>(null);

  if (!character) return null;
  const hasHeroLayout = portraits.length > 0;
  const portrait = portraits[portraitIndex % Math.max(portraits.length, 1)];
  const displayAvatar = character.avatar || presetImages?.avatar || null;
  const expansionProgress = Math.min(scrollTop / 180, 1);
  const isExpanded = expansionProgress >= 0.98;
  const handleScroll = (event: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(event.currentTarget.scrollTop);
  };
  const handleSwipeHintClick = () => {
    dragProps.ref.current?.scrollTo({ top: 180, behavior: 'smooth' });
  };
  const handlePortraitPointerUp = (event: React.PointerEvent<HTMLDivElement>) => {
    if (isExpanded || portraits.length < 2 || portraitStartX === null) return;
    const distance = event.clientX - portraitStartX;
    setPortraitStartX(null);
    if (Math.abs(distance) < 40) return;
    setPortraitIndex(index => (distance < 0 ? (index + 1) % portraits.length : (index - 1 + portraits.length) % portraits.length));
  };

  const personalityTags = splitTags(character.personality);
  const fetishTags = splitTags(character.privateProfile?.fetishTags);

  const SubItemCard = ({
    label,
    value,
    tag,
    tagTone = 'orange',
  }: {
    label: string;
    value?: string | number;
    tag?: string;
    tagTone?: 'pink' | 'orange' | 'violet' | 'sky';
  }) => (
    <div className="bg-surface rounded-xl p-3 border border-border-default shadow-sm flex flex-col gap-1">
      <div className="flex items-center justify-between gap-2">
        <span className="text-[10px] font-bold text-text-secondary uppercase tracking-wider">{label}</span>
        {tag ? <TagChip text={tag} tone={tagTone} /> : null}
      </div>
      {value !== undefined && value !== '' && (
        <span className="text-xs text-text-primary font-medium leading-relaxed">{value}</span>
      )}
    </div>
  );

  return (
    <BottomSheetModal isOpen={true} onClose={onClose} className={`z-[110] ${hasHeroLayout ? 'character-hero-modal' : ''}`}>
      {hasHeroLayout && (
        <button
          type="button"
          onClick={onClose}
          aria-label="返回"
          className="portrait-back-button absolute left-4 top-14 z-30 flex h-10 w-10 items-center justify-center rounded-full text-text-primary shadow-md backdrop-blur-md"
        >
          <ChevronLeft className="h-5 w-5" />
        </button>
      )}
      <div
        className={`h-full min-h-0 flex-1 overflow-y-auto overflow-x-hidden hide-scrollbar ${hasHeroLayout ? 'pt-0' : 'pt-8 pb-8'}`}
        {...dragProps}
        ref={dragProps.ref}
        onScroll={handleScroll}
      >
        {hasHeroLayout && portrait ? (
          <div
            className="relative h-full w-full overflow-hidden"
            data-no-drag-scroll
            onPointerDown={event => {
              setPortraitStartX(event.clientX);
            }}
            onPointerUp={handlePortraitPointerUp}
          >
            <img
              src={portrait}
              alt={`${character.name}立绘`}
              className="absolute inset-0 h-full w-full object-cover object-top"
            />
            <div className="absolute inset-0 bg-black transition-opacity duration-75" style={{ opacity: expansionProgress * 0.42 }} />
            {!isExpanded && (
              <motion.button
                type="button"
                onClick={handleSwipeHintClick}
                aria-label="向上展开角色详情"
                whileTap={{ scale: 0.92 }}
                transition={{ type: 'spring', stiffness: 500, damping: 20 }}
                className="portrait-swipe-hint absolute bottom-14 left-1/2 origin-center -translate-x-1/2 overflow-hidden rounded-full px-4 py-2 shadow-lg backdrop-blur-md"
              >
                <div className="portrait-swipe-shine pointer-events-none absolute inset-y-0 -left-1/2 w-1/2 -skew-x-12 animate-[portrait-shine_2.2s_ease-in-out_infinite]" />
                <div className="relative flex flex-col items-center gap-0.5">
                  <ChevronsUp className="h-5 w-5 animate-bounce" strokeWidth={2.5} />
                  <span className="text-[11px] font-bold leading-none">向上滑动</span>
                </div>
              </motion.button>
            )}
            {portraits.length > 1 && !isExpanded && (
              <div className="absolute bottom-36 left-1/2 flex -translate-x-1/2 gap-1.5">
                {portraits.map((_, index) => <span key={index} className={`h-1.5 w-1.5 rounded-full ${index === portraitIndex ? 'bg-white' : 'bg-white/50'}`} />)}
              </div>
            )}
          </div>
        ) : null}

        <div
          className={hasHeroLayout ? 'relative z-10 rounded-t-[28px] bg-surface-solid px-5 pt-5 pb-8 shadow-[0_-8px_24px_rgba(0,0,0,0.12)]' : 'px-5'}
          style={hasHeroLayout ? { transform: `translateY(${-expansionProgress * 96}px)` } : undefined}
        >
            {/* Header Profile */}
            <div className="flex items-start gap-5 mb-6 mt-2">
              <div className="relative mt-1">
                <ImageUpload
                  currentImage={displayAvatar}
                  onUpload={(url) => onAvatarUpload(character.id, url)}
                  className="w-[100px] h-[100px] rounded-3xl bg-surface flex-shrink-0 border-2 border-border-default shadow-sm"
                />
              </div>
              <div className="flex-1 min-w-0">
                <h3 className="text-2xl font-bold text-text-primary mb-1">{character.name}</h3>
                {character.nickname && character.isFriend ? (
                  <div className="text-xs text-text-secondary mb-2">网名：{character.nickname}</div>
                ) : null}
                
                <div className="flex flex-col gap-2">
                  {personalityTags.length > 0 && (
                    <div className="flex items-start gap-1.5">
                      <Sparkles className="w-3 h-3 text-[color:var(--action-text)] mt-1 shrink-0" />
                      <div className="flex flex-wrap gap-1">
                        {personalityTags.map(tag => (
                          <TagChip key={tag} text={tag} tone="pink" />
                        ))}
                      </div>
                    </div>
                  )}
                  
                  {character.identity && (
                    <div className="flex items-center gap-1.5 soft-chip px-2 py-1 rounded-lg text-xs font-medium self-start">
                      <User className="w-3 h-3" />
                      <span className="truncate">{character.identity}</span>
                    </div>
                  )}
                  
                  {character.className && (
                    <div className="flex items-center gap-1.5 soft-chip px-2 py-1 rounded-lg text-xs font-medium self-start">
                      <GraduationCap className="w-3 h-3" />
                      <span className="truncate">{character.className}</span>
                    </div>
                  )}
                </div>
              </div>
            </div>

            {/* Status Section */}
            <Card className="mb-6 space-y-4">
              {/* Affinity */}
              <div>
                <div className="flex justify-between items-center mb-1.5">
                  <div className="flex items-center gap-1.5 text-xs font-bold text-[color:var(--action-text)]">
                    <Heart className="w-3.5 h-3.5 fill-[color:var(--action-text)]" />
                    好感度
                  </div>
                  <span className="text-xs font-bold text-text-primary">{character.affinity}/100</span>
                </div>
                <div className="h-2.5 w-full bg-surface rounded-full overflow-hidden border border-border-default">
                  <motion.div 
                    initial={{ width: 0 }}
                    animate={{ width: `${character.affinity}%` }}
                    transition={{ duration: 1, delay: 0.2 }}
                    className="h-full affinity-fill rounded-full"
                  />
                </div>
              </div>
              
              {/* Location */}
              <div className="flex items-center gap-2">
                <div className="p-1.5 bg-surface rounded-lg shrink-0 border border-border-default">
                  <MapPin className="w-3.5 h-3.5 text-text-secondary" />
                </div>
                <div className="flex-1">
                  <div className="text-[10px] font-bold text-text-secondary">当前所在地</div>
                  <div className="text-xs font-medium text-text-primary">{character.location}</div>
                </div>
              </div>

              {/* Inner Thoughts */}
              {character.innerThoughts && (
                <div className="flex items-start gap-2 bg-surface p-3 rounded-xl border border-border-default shadow-sm relative">
                  <MessageCircleHeart className="w-4 h-4 text-rose-400 shrink-0 mt-0.5" />
                  <div className="flex-1">
                    <div className="text-[10px] font-bold text-text-secondary mb-0.5">内心所想</div>
                    <div className="text-xs text-text-primary font-medium italic">"{character.innerThoughts}"</div>
                  </div>
                </div>
              )}
            </Card>

            <div className="space-y-4">
              {/* Appearance */}
              <Card>
                <div className="flex items-center gap-1.5 text-sm font-bold text-text-primary mb-3">
                  <Star className="w-4 h-4 text-yellow-500 fill-yellow-500" />
                  容貌
                </div>
                <div className="flex flex-col gap-2">
                  <SubItemCard label="五官" value={character.appearance.features} />
                  <SubItemCard label="发型" value={character.appearance.hairstyle} />
                  <SubItemCard label="皮肤" value={character.appearance.skin} />
                  <SubItemCard label="气质" value={character.appearance.temperament} />
                </div>
              </Card>

              {/* Figure */}
              <Card>
                <div className="flex items-center gap-1.5 text-sm font-bold text-text-primary mb-3">
                  <Star className="w-4 h-4 text-orange-500 fill-orange-500" />
                  身材
                </div>
                <div className="flex flex-col gap-2">
                  <SubItemCard label="胸部" tag={character.figure.chestCup} value={character.figure.chest || '未填写'} />
                  <SubItemCard label="腰部" tag={character.figure.waistType} value={character.figure.waist || '未填写'} />
                  <SubItemCard label="臀部" tag={character.figure.hipType} value={character.figure.buttocks || '未填写'} />
                  <SubItemCard label="腿部" tag={character.figure.legType} value={character.figure.legs || '未填写'} />
                </div>
              </Card>

              <ClothingInfo clothing={character.clothing || { upper: '', lower: '', underwear: '', accessories: '', shoes: '' }} showUnderwear />

              {/* Private Parts */}
              <Card>
                <div className="flex items-center gap-1.5 text-sm font-bold text-text-primary mb-3">
                  <Star className="w-4 h-4 text-rose-500 fill-rose-500" />
                  隐私部位
                </div>
                <div className="flex flex-col gap-2">
                  <SubItemCard label="前庭" value={character.privateParts.pussy} />
                  <SubItemCard label="后庭" value={character.privateParts.anus} />
                </div>
              </Card>

              {/* Experience Profile */}
              <Card>
                <div className="flex items-center gap-1.5 text-sm font-bold text-text-primary mb-3">
                  <Star className="w-4 h-4 text-violet-500 fill-violet-500" />
                  经验档案
                </div>
                <div className="flex flex-col gap-2">
                  <SubItemCard label="是否处女" value={character.privateProfile.isVirgin ? '是' : '否'} />
                  <div className="bg-surface rounded-xl p-3 border border-border-default shadow-sm flex flex-col gap-2">
                    <span className="text-[10px] font-bold text-text-secondary uppercase tracking-wider">性癖标签</span>
                    {fetishTags.length ? (
                      <div className="flex flex-wrap gap-1.5">
                        {fetishTags.map(tag => (
                          <TagChip key={tag} text={tag} tone="violet" />
                        ))}
                      </div>
                    ) : (
                      <span className="text-xs text-text-primary font-medium">无</span>
                    )}
                  </div>
                  <SubItemCard label="经验次数" value={`${character.privateProfile.sexCount} 次`} />
                </div>
              </Card>
            </div>
          </div>
        </div>
    </BottomSheetModal>
  );
}
