import type { CampusPlace, CampusZone } from '../状态栏/src/types';

export interface CampusLocationData {
  分区: Array<{ 名称: string; 类型: string; 排序: number }>;
  地点: Array<{ 名称: string; 所属分区: string; 类型: string; 描述: string; 状态: CampusPlace['status']; 剧情重要: boolean; 发现状态: CampusPlace['discovery'] }>;
}

export function normalizeCampusLocations(value: unknown): CampusLocationData {
  const raw = (value && typeof value === 'object' ? value : {}) as Record<string, any>;
  const rawZones = raw.分区 ?? raw.zones;
  const rawPlaces = raw.地点 ?? raw.places;
  const zoneAliases = new Map<string, string>();
  const zones: CampusLocationData['分区'] = [];
  for (const item of Array.isArray(rawZones) ? rawZones : []) {
    const name = String(typeof item === 'string' ? item : item?.名称 ?? item?.name ?? '').trim();
    if (!name || name === '$__META_EXTENSIBLE__$') continue;
    zoneAliases.set(String(item?.id ?? name), name);
    if (!zones.some(zone => zone.名称 === name)) {
      zones.push({ 名称: name, 类型: String(item?.类型 ?? item?.type ?? '区域'), 排序: Number(item?.排序 ?? item?.order) || zones.length + 1 });
    }
  }
  const places: CampusLocationData['地点'] = [];
  for (const item of Array.isArray(rawPlaces) ? rawPlaces : []) {
    const name = String(typeof item === 'string' ? item : item?.名称 ?? item?.name ?? '').trim();
    if (!name || name === '$__META_EXTENSIBLE__$' || places.some(place => place.名称 === name)) continue;
    const reference = String(item?.所属分区 ?? item?.zoneId ?? '').trim();
    const zone = zoneAliases.get(reference) ?? reference;
    if (zone && !zones.some(item => item.名称 === zone)) zones.push({ 名称: zone, 类型: '区域', 排序: zones.length + 1 });
    const status = item?.状态 ?? item?.status;
    places.push({
      名称: name, 所属分区: zone, 类型: String(item?.类型 ?? item?.type ?? '其他'),
      描述: String(item?.描述 ?? item?.description ?? ''),
      状态: status === '关闭' || status === '未开放' ? status : '开放',
      剧情重要: (item?.剧情重要 ?? item?.important) !== false,
      发现状态: (item?.发现状态 ?? item?.discovery) === '未发现' ? '未发现' : '已知',
    });
  }
  return { 分区: zones, 地点: places };
}

export function campusLocationsToPreview(value: unknown): { zones: CampusZone[]; places: CampusPlace[] } {
  const data = normalizeCampusLocations(value);
  return {
    zones: data.分区.map(zone => ({ id: zone.名称, name: zone.名称, type: zone.类型, order: zone.排序 })),
    places: data.地点.map(place => ({ id: place.名称, name: place.名称, zoneId: place.所属分区 || undefined, type: place.类型, description: place.描述, status: place.状态, important: place.剧情重要, discovery: place.发现状态 })),
  };
}

export function repairCampusArraySchema(variables: unknown): void {
  if (!variables || typeof variables !== 'object') return;
  const schema = (variables as Record<string, any>).schema;
  const buildings = schema?.type === 'object' ? schema.properties?.校园建筑 : undefined;
  if (buildings?.type !== 'object') return;
  for (const building of Object.values(buildings.properties ?? {}) as any[]) {
    if (building?.type !== 'object') continue;
    for (const field of ['分区', '地点', '建筑活动']) {
      const arraySchema = building.properties?.[field];
      if (arraySchema?.type === 'array') arraySchema.extensible = true;
    }
  }
}

export function registerCampusArraySchemaRepair(): void {
  eventOn(Mvu.events.VARIABLE_UPDATE_STARTED, repairCampusArraySchema);
  eventOn(Mvu.events.COMMAND_PARSED, repairCampusArraySchema);
}

export function normalizeCampusLocationData(value: unknown): unknown {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return value;
  const root = value as Record<string, any>;
  if (!root.校园建筑 || typeof root.校园建筑 !== 'object') return value;
  const resolve = (person: any) => {
    if (!person || typeof person !== 'object' || !person.当前具体地点) return person;
    const building = root.校园建筑[person.当前所在地];
    const places = building?.地点 ?? building?.places;
    const place = (Array.isArray(places) ? places : []).find(item => item?.id === person.当前具体地点);
    return place ? { ...person, 当前具体地点: place.名称 ?? place.name ?? person.当前具体地点 } : person;
  };
  return {
    ...root,
    ...(root.玩家 ? { 玩家: resolve(root.玩家) } : {}),
    ...(root.角色 && typeof root.角色 === 'object' ? { 角色: Object.fromEntries(Object.entries(root.角色).map(([name, person]) => [name, resolve(person)])) } : {}),
    校园建筑: Object.fromEntries(Object.entries(root.校园建筑).map(([name, building]) => [name, name === '$meta' || !building || typeof building !== 'object' ? building : { ...building, ...normalizeCampusLocations(building) }])),
  };
}
