import { DEFAULT_APPEARANCES, DEFAULT_PERSONALITIES, Gender, TraitGender, TraitOption, getTraitGender } from './constants';

const CUSTOM_APPEARANCE_KEY = 'campus-app-custom-appearances';
const CUSTOM_PERSONALITY_KEY = 'campus-app-custom-personalities';

function getStorage(): Storage | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

function loadCustomTraits(key: string): TraitOption[] {
  const storage = getStorage();
  if (!storage) return [];
  try {
    const raw = storage.getItem(key);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as TraitOption[];
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter(item => item && typeof item.name === 'string' && item.name.trim())
      .map(item => ({
        id: item.id || `custom-${item.name}`,
        name: item.name.trim(),
        description: String(item.description || '').trim(),
        gender: item.gender === '男' ? '男' : '女',
        custom: true,
      }));
  } catch {
    return [];
  }
}

function saveCustomTraits(key: string, traits: TraitOption[]) {
  const storage = getStorage();
  if (!storage) return;
  try {
    storage.setItem(key, JSON.stringify(traits));
  } catch {
    // ignore quota / private mode
  }
}

function mergeTraits(defaults: TraitOption[], custom: TraitOption[], gender: TraitGender): TraitOption[] {
  const usedIds = new Set(defaults.map(item => item.id));
  const extras = custom.filter(item => {
    if (item.gender !== gender) return false;
    if (usedIds.has(item.id)) return false;
    usedIds.add(item.id);
    return true;
  });
  return [...defaults.filter(item => item.gender === gender), ...extras];
}

export function loadAppearances(gender: Gender): TraitOption[] {
  return mergeTraits(DEFAULT_APPEARANCES, loadCustomTraits(CUSTOM_APPEARANCE_KEY), getTraitGender(gender));
}

export function loadPersonalities(gender: Gender): TraitOption[] {
  const custom = loadCustomTraits(CUSTOM_PERSONALITY_KEY);
  if (gender === '扶她') {
    return [
      ...mergeTraits(DEFAULT_PERSONALITIES, custom, '女'),
      ...mergeTraits(DEFAULT_PERSONALITIES, custom, '男'),
    ];
  }
  return mergeTraits(DEFAULT_PERSONALITIES, custom, getTraitGender(gender));
}

export function loadCustomAppearances(): TraitOption[] {
  return loadCustomTraits(CUSTOM_APPEARANCE_KEY);
}

export function loadCustomPersonalities(): TraitOption[] {
  return loadCustomTraits(CUSTOM_PERSONALITY_KEY);
}

export function deleteCustomAppearance(id: string): boolean {
  const next = loadCustomTraits(CUSTOM_APPEARANCE_KEY).filter(item => item.id !== id);
  if (next.length === loadCustomTraits(CUSTOM_APPEARANCE_KEY).length) return false;
  saveCustomTraits(CUSTOM_APPEARANCE_KEY, next);
  return true;
}

export function deleteCustomPersonality(id: string): boolean {
  const next = loadCustomTraits(CUSTOM_PERSONALITY_KEY).filter(item => item.id !== id);
  if (next.length === loadCustomTraits(CUSTOM_PERSONALITY_KEY).length) return false;
  saveCustomTraits(CUSTOM_PERSONALITY_KEY, next);
  return true;
}

function upsertCustomTraits(key: string, incoming: TraitOption[]): number {
  const current = loadCustomTraits(key);
  const byId = new Map(current.map(item => [item.id, item]));
  let written = 0;
  for (const item of incoming) {
    const name = String(item?.name || '').trim();
    if (!name) continue;
    const id = String(item.id || '').trim() || `custom-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
    byId.set(id, {
      id,
      name,
      description: String(item.description || '').trim(),
      gender: item.gender === '男' ? '男' : '女',
      custom: true,
    });
    written += 1;
  }
  saveCustomTraits(key, [...byId.values()]);
  return written;
}

export function upsertCustomAppearances(incoming: TraitOption[]): number {
  return upsertCustomTraits(CUSTOM_APPEARANCE_KEY, incoming);
}

export function upsertCustomPersonalities(incoming: TraitOption[]): number {
  return upsertCustomTraits(CUSTOM_PERSONALITY_KEY, incoming);
}

export function addCustomAppearance(gender: Gender, name: string, description: string): TraitOption {
  const traitGender = getTraitGender(gender);
  const trait: TraitOption = {
    id: `custom-look-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
    name: name.trim(),
    description: description.trim(),
    gender: traitGender,
    custom: true,
  };
  saveCustomTraits(CUSTOM_APPEARANCE_KEY, [...loadCustomTraits(CUSTOM_APPEARANCE_KEY), trait]);
  return trait;
}

export function addCustomPersonality(gender: Gender, name: string, description: string): TraitOption {
  const traitGender = getTraitGender(gender);
  const trait: TraitOption = {
    id: `custom-mind-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
    name: name.trim(),
    description: description.trim(),
    gender: traitGender,
    custom: true,
  };
  saveCustomTraits(CUSTOM_PERSONALITY_KEY, [...loadCustomTraits(CUSTOM_PERSONALITY_KEY), trait]);
  return trait;
}
