export function getTavernInput(): HTMLTextAreaElement | null {
  const docs: Document[] = [];
  try {
    if (window.parent !== window) docs.push(window.parent.document);
  } catch {
    // Cross-origin hosts cannot expose the native composer.
  }
  docs.push(document);
  for (const doc of docs) {
    const input = doc.querySelector<HTMLTextAreaElement>(
      '#send_textarea, textarea[name="send_textarea"], textarea#chat-input',
    );
    if (input) return input;
  }
  return null;
}

export function setTavernInput(value: string): boolean {
  const input = getTavernInput();
  if (!input || input.disabled || input.readOnly) return false;
  const view = input.ownerDocument.defaultView;
  if (!view) return false;
  const realm = view as Window & typeof globalThis;
  const setter = Object.getOwnPropertyDescriptor(realm.HTMLTextAreaElement.prototype, 'value')?.set;
  if (setter) setter.call(input, value);
  else input.value = value;
  input.dispatchEvent(new realm.Event('input', { bubbles: true }));
  input.dispatchEvent(new realm.Event('change', { bubbles: true }));
  return true;
}

export function isTavernGenerating(): boolean {
  return Boolean(getTavernInput()?.ownerDocument.querySelector<HTMLElement>('#mes_stop')?.checkVisibility());
}

export function clickTavernStop(): void {
  const stop = getTavernInput()?.ownerDocument.querySelector<HTMLElement>('#mes_stop');
  if (!stop?.checkVisibility()) throw new Error('酒馆当前没有可中止的生成。');
  stop.click();
}

export function clickTavernSend(): void {
  const input = getTavernInput();
  if (!input) throw new Error('未找到酒馆输入栏，请确认已打开聊天。');
  const doc = input.ownerDocument;
  const send = doc.querySelector<HTMLElement>('#send_but');
  if (
    !send ||
    input.disabled ||
    input.readOnly ||
    send.matches(':disabled, [aria-disabled="true"], .disabled') ||
    doc.querySelector('#mes_stop')?.checkVisibility()
  ) {
    throw new Error('酒馆暂时无法发送，请稍后重试。');
  }
  if (!send.checkVisibility()) throw new Error('酒馆发送按钮不可用，草稿已保留。');
  if (!input.value.trim()) throw new Error('请先输入内容。');
  send.click();
}

export function fillTavernInput(text: string): boolean {
  const value = text.trim();
  if (!value) return false;

  const textarea = getTavernInput();
  if (!textarea) return false;
  const existing = textarea.value.replace(/\s+$/, '');
  const next = existing ? `${existing}\n${value}` : value;
  if (!setTavernInput(next)) return false;
  textarea.focus();
  textarea.setSelectionRange(next.length, next.length);
  return true;
}
