import { Shirt } from 'lucide-react';
import React from 'react';
import { Clothing } from '../../types';
import { Card } from '../ui/Card';

interface ClothingInfoProps {
  clothing: Clothing;
  showUnderwear?: boolean;
}

const ClothingItem: React.FC<{ label: string; value: string }> = ({ label, value }) => {
  const text = value?.trim() || '未填写';

  return (
    <div className="bg-surface rounded-xl p-3 border border-border-default shadow-sm flex flex-col gap-1">
      <span className="text-[10px] font-bold text-text-secondary uppercase tracking-wider">{label}</span>
      <p className="text-xs text-text-primary font-medium leading-relaxed whitespace-pre-wrap break-words">{text}</p>
    </div>
  );
};

export const ClothingInfo: React.FC<ClothingInfoProps> = ({ clothing, showUnderwear = false }) => {
  const clothingItems = [
    { label: '当前上装', val: clothing.upper },
    { label: '当前下装', val: clothing.lower },
    ...(showUnderwear ? [{ label: '当前内衣', val: clothing.underwear || '' }] : []),
    { label: '随身配饰', val: clothing.accessories },
    { label: '当前鞋履', val: clothing.shoes },
  ];

  return (
    <Card className="p-4">
      <div className="flex items-center gap-1.5 text-sm font-bold text-text-primary mb-3">
        <Shirt className="w-4 h-4 text-sky-500" />
        衣着
      </div>
      <div className="flex flex-col gap-2">
        {clothingItems.map(item => (
          <ClothingItem key={item.label} label={item.label} value={item.val} />
        ))}
      </div>
    </Card>
  );
};
