import { useCallback, useEffect, useState } from 'react';
import { FORUM_STATE_EVENT, cancelForumGeneration, forumErrorMessage, generateForumPosts, isForumGenerating, readForumGenerationConfig, readForumState, saveForumGenerationConfig, ForumGenerationConfig } from '../utils/forumGeneration';

export function useForumGeneration() {
  const [config, setConfig] = useState(readForumGenerationConfig);
  const [state, setState] = useState(readForumState);
  const [busy, setBusy] = useState(isForumGenerating);
  const [progress, setProgress] = useState(0);
  useEffect(() => {
    const sync = () => {
      setState(previous => { const next = readForumState(); return _.isEqual(previous, next) ? previous : next; });
      setConfig(previous => { const next = readForumGenerationConfig(); return _.isEqual(previous, next) ? previous : next; });
      setBusy(isForumGenerating());
    };
    window.addEventListener(FORUM_STATE_EVENT, sync);
    window.addEventListener('storage', sync);
    const subscription = typeof eventOn === 'function' ? eventOn(tavern_events.CHAT_CHANGED, sync) : undefined;
    const timer = window.setInterval(sync, 800);
    sync();
    return () => { window.removeEventListener(FORUM_STATE_EVENT, sync); window.removeEventListener('storage', sync); subscription?.stop(); window.clearInterval(timer); };
  }, []);
  const updateConfig = useCallback((patch: Partial<ForumGenerationConfig>) => {
    try { saveForumGenerationConfig({ ...readForumGenerationConfig(), ...patch }); }
    catch (error) { throw new Error(`无法保存设置：${forumErrorMessage(error)}`); }
  }, []);
  const generate = useCallback(async () => { await generateForumPosts(); return true; }, []);
  const cancel = useCallback(() => cancelForumGeneration(), []);
  const status = busy ? 'generating' : state.lastError ? 'error' : state.lastGeneratedAt ? 'success' : 'idle';
  return { config, state, status, busy, progress, setProgress, updateConfig, generate, cancel };
}
