import { Plus, Trash2 } from 'lucide-react';
import { ReactNode } from 'react';
import { GENDERS } from './constants';
import { createManifestationStage, createTraitGroup, NamedTraitGroup, RoleArchiveForm } from './classmates';

interface RoleArchiveFormFieldsProps {
  form: RoleArchiveForm;
  onChange: (form: RoleArchiveForm) => void;
}

function Field({
  label,
  value,
  onChange,
  placeholder,
}: {
  label: string;
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
}) {
  return (
    <label className="block mb-3 last:mb-0 min-w-0">
      <span className="text-xs font-bold text-text-secondary mb-1.5 block">{label}</span>
      <input
        value={value}
        onChange={event => onChange(event.target.value)}
        placeholder={placeholder}
        className="box-border w-full max-w-full min-w-0 h-10 rounded-xl px-3 theme-field"
      />
    </label>
  );
}

function StringList({
  values,
  onChange,
  placeholder,
  addLabel,
}: {
  values: string[];
  onChange: (values: string[]) => void;
  placeholder: string;
  addLabel: string;
}) {
  const items = values.length ? values : [''];
  return (
    <div className="space-y-2 min-w-0">
      {items.map((value, index) => (
        <div key={index} className="flex items-center gap-2 min-w-0 w-full">
          <input
            value={value}
            onChange={event => onChange(items.map((item, itemIndex) => (itemIndex === index ? event.target.value : item)))}
            placeholder={placeholder}
            className="box-border w-0 min-w-0 flex-1 h-10 rounded-xl px-3 theme-field"
          />
          {items.length > 1 && (
            <button
              type="button"
              onClick={() => onChange(items.filter((_, itemIndex) => itemIndex !== index))}
              className="w-8 h-8 shrink-0 rounded-xl border border-border-default text-text-secondary flex items-center justify-center"
            >
              <Trash2 className="w-3.5 h-3.5" />
            </button>
          )}
        </div>
      ))}
      <button
        type="button"
        onClick={() => onChange([...items, ''])}
        className="w-full py-2 rounded-xl theme-dashed-btn text-xs font-bold flex items-center justify-center gap-1"
      >
        <Plus className="w-3.5 h-3.5" />
        {addLabel}
      </button>
    </div>
  );
}

function SubSection({ title, children }: { title: string; children: ReactNode }) {
  return (
    <div className="mb-3 last:mb-0 rounded-xl theme-panel p-3 min-w-0 overflow-hidden">
      <p className="text-xs font-bold text-selected-text mb-2">{title}</p>
      {children}
    </div>
  );
}

function Section({ title, children }: { title: string; children: ReactNode }) {
  return (
    <div className="mb-4 rounded-2xl theme-panel p-3 min-w-0 overflow-hidden">
      <p className="text-sm font-bold text-text-primary mb-3">{title}</p>
      {children}
    </div>
  );
}

function TraitGroupList({
  groups,
  onChange,
  namePlaceholder,
  itemPlaceholder,
  addGroupLabel,
}: {
  groups: NamedTraitGroup[];
  onChange: (groups: NamedTraitGroup[]) => void;
  namePlaceholder: string;
  itemPlaceholder: string;
  addGroupLabel: string;
}) {
  const items = groups.length ? groups : [createTraitGroup()];
  return (
    <div className="space-y-3 min-w-0">
      {items.map(group => {
        const stages = group.stages || [];
        const showDirectList = stages.length === 0;
        return (
        <div key={group.id} className="rounded-xl theme-panel p-3 min-w-0 overflow-hidden">
          <div className="flex items-center gap-2 mb-3 min-w-0 w-full">
            <input
              value={group.name}
              onChange={event =>
                onChange(items.map(item => (item.id === group.id ? { ...item, name: event.target.value } : item)))
              }
              placeholder={namePlaceholder}
              className="box-border w-0 min-w-0 flex-1 h-10 rounded-xl px-3 theme-field"
            />
            {items.length > 1 && (
              <button
                type="button"
                onClick={() => onChange(items.filter(item => item.id !== group.id))}
                className="w-8 h-8 shrink-0 rounded-xl border border-border-default text-text-secondary flex items-center justify-center"
              >
                <Trash2 className="w-3.5 h-3.5" />
              </button>
            )}
          </div>
          <p className="text-xs font-bold text-text-secondary mb-1.5">表现形式</p>
          {showDirectList && (
            <StringList
              values={group.manifestations}
              onChange={manifestations =>
                onChange(items.map(item => (item.id === group.id ? { ...item, manifestations } : item)))
              }
              placeholder={itemPlaceholder}
              addLabel="新增表现形式"
            />
          )}
          <div className={`${showDirectList ? 'mt-3' : ''} space-y-2 min-w-0`}>
            {(group.stages || []).map(stage => (
              <div key={stage.id} className="rounded-xl theme-selected p-2.5 min-w-0">
                <div className="flex items-center gap-2 mb-2 min-w-0 w-full">
                  <input
                    value={stage.name}
                    onChange={event =>
                      onChange(
                        items.map(item =>
                          item.id === group.id
                            ? {
                                ...item,
                                stages: item.stages.map(current =>
                                  current.id === stage.id ? { ...current, name: event.target.value } : current,
                                ),
                              }
                            : item,
                        ),
                      )
                    }
                    placeholder="如：前戏阶段"
                    className="box-border w-0 min-w-0 flex-1 h-9 rounded-xl px-3 theme-field"
                  />
                  <button
                    type="button"
                    onClick={() =>
                      onChange(
                        items.map(item =>
                          item.id === group.id
                            ? { ...item, stages: item.stages.filter(current => current.id !== stage.id) }
                            : item,
                        ),
                      )
                    }
                    className="w-8 h-8 shrink-0 rounded-xl border border-border-default text-text-secondary flex items-center justify-center"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
                <StringList
                  values={stage.items}
                  onChange={values =>
                    onChange(
                      items.map(item =>
                        item.id === group.id
                          ? {
                              ...item,
                              stages: item.stages.map(current =>
                                current.id === stage.id ? { ...current, items: values } : current,
                              ),
                            }
                          : item,
                      ),
                    )
                  }
                  placeholder="该阶段的具体表现"
                  addLabel="新增该阶段表现"
                />
              </div>
            ))}
            <button
              type="button"
              onClick={() =>
                onChange(
                  items.map(item =>
                    item.id === group.id
                      ? { ...item, stages: [...(item.stages || []), createManifestationStage()], manifestations: [] }
                      : item,
                  ),
                )
              }
              className="w-full py-2 rounded-xl theme-dashed-btn text-xs font-bold flex items-center justify-center gap-1 bg-surface-solid"
            >
              <Plus className="w-3.5 h-3.5" />
              新增阶段
            </button>
          </div>
        </div>
        );
      })}
      <button
        type="button"
        onClick={() => onChange([...items, createTraitGroup()])}
        className="w-full py-2 rounded-xl theme-dashed-btn text-xs font-bold flex items-center justify-center gap-1"
      >
        <Plus className="w-3.5 h-3.5" />
        {addGroupLabel}
      </button>
    </div>
  );
}

