import { useEffect, useRef, useState } from 'react';
import { Check, ChevronDown, RefreshCw } from 'lucide-react';
import { ForumGenerationConfig, detectForumModels, forumErrorMessage, testForumConnection } from '../../utils/forumGeneration';
import { showToast } from '../ui/Toast';

export function ForumApiSettings({ config, onChange }: { config: ForumGenerationConfig; onChange: (patch: Partial<ForumGenerationConfig>) => void }) {
  const [testing, setTesting] = useState(false);
  const [models, setModels] = useState<string[]>([]);
  const [detecting, setDetecting] = useState(false);
  const [modelError, setModelError] = useState('');
  const [modelOpen, setModelOpen] = useState(false);
  const [filter, setFilter] = useState('');
  const [manual, setManual] = useState(false);
  const requestRef = useRef<AbortController | null>(null);
  const pickerRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    requestRef.current?.abort();
    requestRef.current = null;
    setModels([]); setDetecting(false); setModelError(''); setModelOpen(false); setFilter('');
    return () => { requestRef.current?.abort(); requestRef.current = null; };
  }, [config.apiUrl, config.apiKey, config.apiSource]);
  useEffect(() => {
    if (!modelOpen) return;
    const outside = (event: PointerEvent) => { if (!pickerRef.current?.contains(event.target as Node)) setModelOpen(false); };
    const escape = (event: KeyboardEvent) => { if (event.key === 'Escape') { setModelOpen(false); triggerRef.current?.focus(); } };
    document.addEventListener('pointerdown', outside);
    document.addEventListener('keydown', escape);
    return () => { document.removeEventListener('pointerdown', outside); document.removeEventListener('keydown', escape); };
  }, [modelOpen]);
  const detect = async () => {
    if (requestRef.current) return;
    const request = new AbortController();
    requestRef.current = request;
    setDetecting(true); setModelError('');
    try {
      const next = await detectForumModels(config, request.signal);
      if (requestRef.current !== request || request.signal.aborted) return;
      setModels(next); setManual(false); setFilter(''); setModelOpen(true);
      showToast(`检测到 ${next.length} 个模型`, 'success');
    } catch (error) {
      if (requestRef.current === request && !request.signal.aborted) setModelError(forumErrorMessage(error));
    } finally {
      if (requestRef.current === request) { requestRef.current = null; setDetecting(false); }
    }
  };
  const inputClass = 'mt-1.5 w-full min-w-0 rounded-xl border border-border-default bg-surface px-3 py-2 text-xs text-text-primary outline-none focus:border-[color:var(--action-text)]';
  const test = async () => {
    if (testing) return;
    setTesting(true);
    try { await testForumConnection(config); showToast('API 连接成功', 'success'); }
    catch (error) { showToast(forumErrorMessage(error), 'error'); }
    finally { setTesting(false); }
  };
  return <div className="space-y-3 border-t border-border-default/50 pt-3">
    <div className="text-xs font-semibold text-text-primary">API 来源</div>
    <div className="grid grid-cols-2 gap-2" role="group" aria-label="API 来源">
      {(['tavern', 'custom'] as const).map(source => <button key={source} type="button" aria-pressed={config.apiSource === source} onClick={() => onChange({ apiSource: source })} className={`rounded-xl border px-2 py-2 text-xs font-semibold ${config.apiSource === source ? 'accent-btn' : 'border-border-default bg-surface text-text-secondary'}`}>{source === 'tavern' ? '沿用酒馆' : '自定义 API'}</button>)}
    </div>
    {config.apiSource === 'tavern' && <p className="text-[10px] leading-relaxed text-text-secondary">模型沿用酒馆当前选择；如需单独选择论坛模型，请切换为自定义 API。</p>}
    {config.apiSource === 'custom' && <div className="space-y-3">
      <label className="block text-[11px] text-text-secondary">API 地址<input type="url" value={config.apiUrl} onChange={event => onChange({ apiUrl: event.target.value })} placeholder="https://your-provider.example/v1" className={inputClass} autoComplete="off" /></label>
      <label className="block text-[11px] text-text-secondary">API Key<input type="password" value={config.apiKey} onChange={event => onChange({ apiKey: event.target.value })} placeholder="可选，按服务商要求填写" className={inputClass} autoComplete="off" spellCheck={false} /></label>
      <div className="text-[11px] text-text-secondary">
        <div className="mb-1.5 flex items-center justify-between gap-2"><span>模型</span><button type="button" disabled={detecting || !config.apiUrl.trim()} onClick={() => void detect()} className="flex items-center gap-1 rounded-lg border border-border-default px-2 py-1 text-text-primary disabled:opacity-50"><RefreshCw className={`h-3 w-3 ${detecting ? 'animate-spin' : ''}`} />{detecting ? '检测中…' : '检测模型列表'}</button></div>
        <div ref={pickerRef}>
          <button ref={triggerRef} type="button" aria-haspopup="listbox" aria-expanded={modelOpen} onClick={() => { if (models.length) setModelOpen(current => !current); else void detect(); }} disabled={detecting || !config.apiUrl.trim()} className="flex w-full min-w-0 items-center justify-between gap-2 rounded-xl border border-border-default bg-surface px-3 py-2 text-left text-xs text-text-primary disabled:opacity-60"><span className="truncate">{config.model || '检测后选择模型'}</span><ChevronDown className={`h-3.5 w-3.5 shrink-0 transition-transform ${modelOpen ? 'rotate-180' : ''}`} /></button>
          {modelOpen && <div className="mt-2 overflow-hidden rounded-xl border border-border-default bg-surface-solid p-1 shadow-lg">
            <input autoFocus aria-label="搜索模型" placeholder="搜索模型…" value={filter} onChange={event => setFilter(event.target.value)} className="mb-1 w-full rounded-lg border border-border-default bg-surface px-2.5 py-2 text-xs text-text-primary outline-none" />
            <div role="listbox" aria-label="可用模型" className="max-h-44 overflow-y-auto overscroll-contain">
              {models.filter(model => model.toLowerCase().includes(filter.toLowerCase())).map(model => <button key={model} type="button" role="option" aria-selected={config.model === model} onClick={() => { onChange({ model }); setModelOpen(false); triggerRef.current?.focus(); }} className={`flex w-full items-center justify-between gap-2 rounded-lg px-2.5 py-2 text-left text-xs ${config.model === model ? 'accent-btn' : 'text-text-primary hover:bg-surface'}`}><span className="min-w-0 break-all">{model}</span>{config.model === model && <Check className="h-3.5 w-3.5 shrink-0" />}</button>)}
              {!models.some(model => model.toLowerCase().includes(filter.toLowerCase())) && <p className="px-2 py-3 text-center">没有匹配的模型</p>}
            </div>
          </div>}
        </div>
        {modelError && <p role="alert" className="mt-2 break-words text-rose-500">{modelError}</p>}
        <button type="button" onClick={() => setManual(value => !value)} className="mt-2 underline underline-offset-2">{manual ? '收起手动输入' : '手动填写模型名称'}</button>
        {manual && <input aria-label="手动模型名称" value={config.model} onChange={event => onChange({ model: event.target.value })} placeholder="服务商提供的模型 ID" className={inputClass} autoComplete="off" />}
        <p className="mt-1.5 text-[10px]">检测通过模型列表接口读取，不发送生成请求；列表中的模型是否支持对话需通过连接测试确认。</p>
      </div>
      <div className="grid grid-cols-2 gap-3">
        <label className="block text-[11px] text-text-secondary">温度<input type="number" min={0} max={2} step={0.1} value={config.temperature} onChange={event => { if (event.target.value) onChange({ temperature: Math.min(2, Math.max(0, Number(event.target.value))) }); }} className={inputClass} /></label>
        <label className="block text-[11px] text-text-secondary">最大输出 Tokens<input type="number" min={64} max={32768} step={64} value={config.maxTokens} onChange={event => { if (event.target.value) onChange({ maxTokens: Math.min(32768, Math.max(64, Math.round(Number(event.target.value)))) }); }} className={inputClass} /></label>
      </div>
      <p className="text-[10px] leading-relaxed text-text-secondary">地址填写与酒馆自定义 API 相同的基础地址。Key 仅保存在本机浏览器，不写入聊天变量；连接测试会发送一条简短请求。</p>
      <button type="button" onClick={() => onChange({ apiKey: '' })} className="text-[11px] text-text-secondary underline underline-offset-2">清除已保存的 Key</button>
    </div>}
    <button type="button" disabled={testing} onClick={() => void test()} className="flex w-full items-center justify-center gap-2 rounded-xl border border-border-default bg-surface py-2.5 text-xs font-semibold text-text-primary disabled:opacity-50"><RefreshCw className={`h-3.5 w-3.5 ${testing ? 'animate-spin' : ''}`} />{testing ? '测试中…' : '测试连接'}</button>
  </div>;
}
