import { ArrowLeftRight, NotebookPen, Smartphone, X } from 'lucide-react';
import { CampusTablet } from '../状态栏/src/components/CampusTablet';
import { ReactNode, useCallback, useEffect, useRef, useState } from 'react';
import { usePhoneCloseMode } from '../状态栏/src/hooks/usePhoneCloseMode';
import { useForumGeneration } from '../状态栏/src/hooks/useForumGeneration';

const HOST_ID = 'campus-app-float-host';
const BUTTON_POS_KEY = 'campus-app-float-pos';
const PANEL_POS_KEY = 'campus-app-float-panel-pos';
const SCALE_KEY = 'campus-app-float-scale';
const BUTTON_SIZE = 72;
const PHONE_WIDTH = 380;
const PHONE_HEIGHT = 720;
const CLOSE_GAP = 10;
const CLOSE_HEIGHT = 36;
const HANDLE_PAD = 18;
const OUTER_CONTROL_GAP = 40;
const HANDLE_SIZE = 20;
const HANDLE_THICK = 4;
const MIN_SCALE = 0.45;
const MAX_SCALE = 1.7;
const DEFAULT_SCALE = 0.8;
const Z_INDEX = '2147483000';
const EDGE = 14;

type Position = { x: number; y: number };
type RestorePoint = { parent: Node; nextSibling: ChildNode | null };
type DragMode = 'button' | 'panel' | 'resize-nw' | 'resize-se';
type DragState = {
  startX: number;
  startY: number;
  originX: number;
  originY: number;
  originScale: number;
  moved: boolean;
  mode: DragMode;
  anchorX: number;
  anchorY: number;
};

let restorePoint: RestorePoint | null = null;

function getFrame(): HTMLIFrameElement | null {
  return (window.frameElement as HTMLIFrameElement | null) ?? null;
}

function isScriptMountedFrame(): boolean {
  const iframe = getFrame();
  if (iframe?.dataset.campusScriptMounted === '1') return true;
  return /TH-script/i.test(iframe?.id || '');
}

function getParentWindow(): Window {
  try {
    return window.parent && window.parent !== window ? window.parent : window;
  } catch {
    return window;
  }
}

function getParentDocument(): Document {
  return getParentWindow().document;
}

function clampPosition(pos: Position, width: number, height: number): Position {
  const parent = getParentWindow();
  const maxX = Math.max(8, parent.innerWidth - width - 8);
  const maxY = Math.max(8, parent.innerHeight - height - 8);
  return {
    x: Math.min(Math.max(8, pos.x), maxX),
    y: Math.min(Math.max(8, pos.y), maxY),
  };
}

function defaultButtonPos(): Position {
  const parent = getParentWindow();
  return clampPosition(
    {
      x: parent.innerWidth - BUTTON_SIZE - 24,
      y: parent.innerHeight - BUTTON_SIZE - 24,
    },
    BUTTON_SIZE,
    BUTTON_SIZE,
  );
}

function clampScale(value: number): number {
  return Math.min(MAX_SCALE, Math.max(MIN_SCALE, value));
}

const TABLET_WIDTH = 1020;
const TABLET_GAP = 12;
const TABLET_KEY = 'campus-app-tablet';

function loadTablet(): { open: boolean; side: 'left' | 'right' } {
  try {
    const value = JSON.parse(getParentWindow().localStorage.getItem(TABLET_KEY) || '{}');
    return { open: value.open === true, side: value.side === 'left' ? 'left' : 'right' };
  } catch {
    return { open: false, side: 'right' };
  }
}

function panelSize(scale: number, closeOnOutside = false, tabletOpen = false) {
  return {
    width: Math.round(
      (PHONE_WIDTH + (tabletOpen ? TABLET_WIDTH + TABLET_GAP : 0)) * scale + HANDLE_PAD * 2 + OUTER_CONTROL_GAP,
    ),
    height: Math.round(PHONE_HEIGHT * scale + HANDLE_PAD * 2 + (closeOnOutside ? 0 : CLOSE_GAP + CLOSE_HEIGHT)),
  };
}

function defaultPanelPos(scale = DEFAULT_SCALE): Position {
  const parent = getParentWindow();
  const size = panelSize(scale);
  return clampPosition(
    {
      x: Math.round((parent.innerWidth - size.width) / 2),
      y: Math.round((parent.innerHeight - size.height) / 2),
    },
    size.width,
    size.height,
  );
}

function loadPosition(key: string, fallback: () => Position, width: number, height: number): Position {
  try {
    const raw = getParentWindow().localStorage.getItem(key);
    if (raw) {
      const parsed = JSON.parse(raw) as Position;
      if (typeof parsed.x === 'number' && typeof parsed.y === 'number') {
        return clampPosition(parsed, width, height);
      }
    }
  } catch {
    // ignore
  }
  return fallback();
}

function savePosition(key: string, pos: Position) {
  try {
    getParentWindow().localStorage.setItem(key, JSON.stringify(pos));
  } catch {
    // ignore
  }
}

function loadScale(): number {
  try {
    const raw = getParentWindow().localStorage.getItem(SCALE_KEY);
    if (raw) {
      const parsed = Number(raw);
      if (Number.isFinite(parsed)) return clampScale(parsed);
    }
  } catch {
    // ignore
  }
  return DEFAULT_SCALE;
}

function saveScale(scale: number) {
  try {
    getParentWindow().localStorage.setItem(SCALE_KEY, String(scale));
  } catch {
    // ignore
  }
}

function ensureHost(): HTMLElement {
  const doc = getParentDocument();
  let host = doc.getElementById(HOST_ID);
  if (!host) {
    host = doc.createElement('div');
    host.id = HOST_ID;
    host.style.cssText = 'position:static;width:0;height:0;overflow:visible;pointer-events:none;';
    doc.body.appendChild(host);
  }
  return host;
}

function applyFrameStyle(
  open: boolean,
  pos: Position,
  scale = DEFAULT_SCALE,
  closeOnOutside = false,
  tabletOpen = false,
) {
  const iframe = getFrame();
  if (!iframe) return;
  iframe.setAttribute('allowtransparency', 'true');
  if (open) {
    const size = panelSize(scale, closeOnOutside, tabletOpen);
    iframe.style.cssText = [
      'position:fixed',
      `left:${pos.x}px`,
      `top:${pos.y}px`,
      `width:${size.width}px`,
      `height:${size.height}px`,
      'border:none',
      'margin:0',
      'padding:0',
      'background:transparent',
      `z-index:${Z_INDEX}`,
      'border-radius:0',
      'box-shadow:none',
      'overflow:visible',
      'pointer-events:auto',
    ].join(';');
    return;
  }

  iframe.style.cssText = [
    'position:fixed',
    `left:${pos.x}px`,
    `top:${pos.y}px`,
    `width:${BUTTON_SIZE}px`,
    `height:${BUTTON_SIZE}px`,
    'border:none',
    'margin:0',
    'padding:0',
    'background:transparent',
    `z-index:${Z_INDEX}`,
    'border-radius:999px',
    'overflow:hidden',
    'box-shadow:0 10px 30px rgba(15,23,42,0.28)',
    'pointer-events:auto',
  ].join(';');
}

function hideFrameInChat() {
  const iframe = getFrame();
  if (!iframe) return;
  iframe.style.cssText = [
    'width:0',
    'height:0',
    'min-width:0',
    'min-height:0',
    'border:none',
    'position:absolute',
    'overflow:hidden',
    'opacity:0',
    'pointer-events:none',
  ].join(';');
}

function mountFrameToHost() {
  const iframe = getFrame();
  if (!iframe) return;
  if (!restorePoint && iframe.parentNode) {
    restorePoint = {
      parent: iframe.parentNode,
      nextSibling: iframe.nextSibling,
    };
  }
  const host = ensureHost();
  const occupying = host.querySelector('iframe');
  if (occupying && occupying !== iframe) {
    const occupyingRestore = (occupying as HTMLIFrameElement & { _campusRestore?: RestorePoint })._campusRestore;
    if (occupyingRestore?.parent) {
      occupyingRestore.parent.insertBefore(occupying, occupyingRestore.nextSibling);
    }
  }
  (iframe as HTMLIFrameElement & { _campusRestore?: RestorePoint })._campusRestore = restorePoint ?? undefined;
  if (iframe.parentNode !== host) {
    host.appendChild(iframe);
  }
}

export function restoreCampusFrame() {
  if (isScriptMountedFrame()) {
    return;
  }
  const iframe = getFrame();
  if (iframe && restorePoint?.parent) {
    restorePoint.parent.insertBefore(iframe, restorePoint.nextSibling);
    hideFrameInChat();
  }
  const host = getParentDocument().getElementById(HOST_ID);
  if (host && host.childElementCount === 0) {
    host.remove();
  }
}

function isLatestFloor(): boolean {
  if (isScriptMountedFrame()) {
    return true;
  }
  try {
    if (typeof getCurrentMessageId === 'function' && typeof getLastMessageId === 'function') {
      return getCurrentMessageId() === getLastMessageId();
    }
  } catch {
    return true;
  }
  return true;
}

function getLatestFloor(): number {
  try {
    if (typeof getLastMessageId === 'function') {
      return getLastMessageId();
    }
  } catch {
    // ignore
  }
  if (isScriptMountedFrame()) {
    return 0;
  }
  try {
    if (typeof getCurrentMessageId === 'function') {
      return getCurrentMessageId();
    }
  } catch {
    return 0;
  }
  return 0;
}

function shouldAutoOpen(): boolean {
  return isLatestFloor() && getLatestFloor() === 0;
}

function toParentPoint(event: PointerEvent | React.PointerEvent): Position {
  if (event.view === getParentWindow()) {
    return { x: event.clientX, y: event.clientY };
  }
  const rect = getFrame()?.getBoundingClientRect();
  if (rect) {
    return { x: rect.left + event.clientX, y: rect.top + event.clientY };
  }
  return { x: event.clientX, y: event.clientY };
}

function ScaleHandle({ corner }: { corner: 'nw' | 'se' }) {
  const isNw = corner === 'nw';
  return (
    <div
      className="pointer-events-none"
      style={{
        position: 'absolute',
        width: HANDLE_SIZE,
        height: HANDLE_SIZE,
        left: isNw ? 0 : undefined,
        top: isNw ? 0 : undefined,
        right: isNw ? undefined : 0,
        bottom: isNw ? undefined : 0,
      }}
    >
      <span
        className="absolute bg-white/55"
        style={{
          width: HANDLE_SIZE,
          height: HANDLE_THICK,
          left: 0,
          top: isNw ? 0 : undefined,
          bottom: isNw ? undefined : 0,
          borderRadius: 1,
        }}
      />
      <span
        className="absolute bg-white/55"
        style={{
          width: HANDLE_THICK,
          height: HANDLE_SIZE,
          left: isNw ? 0 : undefined,
          right: isNw ? undefined : 0,
          top: 0,
          borderRadius: 1,
        }}
      />
    </div>
  );
}

interface FloatingPhoneHostProps {
  children: ReactNode;
}

export function FloatingPhoneHost({ children }: FloatingPhoneHostProps) {
  const scriptMounted = isScriptMountedFrame();
  const { closeOnOutside } = usePhoneCloseMode();
  const { busy: forumGenerating } = useForumGeneration();
  const [active, setActive] = useState(() => scriptMounted || isLatestFloor());
  const [open, setOpen] = useState(() => scriptMounted || shouldAutoOpen());
  const [scale, setScale] = useState(loadScale);
  const [tablet, setTablet] = useState(loadTablet);
  const tabletRef = useRef(tablet);
  tabletRef.current = tablet;
  const changeTablet = (next: typeof tablet) => {
    const viewport = getParentWindow();
    const logicalWidth = PHONE_WIDTH + (next.open ? TABLET_WIDTH + TABLET_GAP : 0);
    const fittedScale = Math.min(
      scaleRef.current,
      Math.max(0.2, (viewport.innerWidth - HANDLE_PAD * 2 - OUTER_CONTROL_GAP - 16) / logicalWidth),
      Math.max(
        0.2,
        (viewport.innerHeight - HANDLE_PAD * 2 - (closeOnOutsideRef.current ? 0 : CLOSE_GAP + CLOSE_HEIGHT) - 16) /
          PHONE_HEIGHT,
      ),
    );
    const extra = (TABLET_WIDTH + TABLET_GAP) * scaleRef.current;
    const oldOffset = tabletRef.current.open && tabletRef.current.side === 'left' ? extra : 0;
    const nextOffset = next.open && next.side === 'left' ? (TABLET_WIDTH + TABLET_GAP) * fittedScale : 0;
    const size = panelSize(fittedScale, closeOnOutsideRef.current, next.open);
    scaleRef.current = fittedScale;
    setScale(fittedScale);
    const pos = clampPosition(
      { x: panelPosRef.current.x + oldOffset - nextOffset, y: panelPosRef.current.y },
      size.width,
      size.height,
    );
    tabletRef.current = next;
    panelPosRef.current = pos;
    setPanelPos(pos);
    setTablet(next);
    savePosition(PANEL_POS_KEY, pos);
    try {
      getParentWindow().localStorage.setItem(TABLET_KEY, JSON.stringify(next));
    } catch {
      /* Storage may be unavailable. */
    }
  };
  const [buttonPos, setButtonPos] = useState<Position>(() =>
    loadPosition(BUTTON_POS_KEY, defaultButtonPos, BUTTON_SIZE, BUTTON_SIZE),
  );
  const [panelPos, setPanelPos] = useState<Position>(() => {
    const initialScale = loadScale();
    const size = panelSize(initialScale);
    return loadPosition(PANEL_POS_KEY, () => defaultPanelPos(initialScale), size.width, size.height);
  });
  const buttonPosRef = useRef(buttonPos);
  const panelPosRef = useRef(panelPos);
  const scaleRef = useRef(scale);
  const openRef = useRef(false);
  const closeOnOutsideRef = useRef(closeOnOutside);
  const autoOpenedRef = useRef(scriptMounted || shouldAutoOpen());
  const dragRef = useRef<DragState | null>(null);

  useEffect(() => {
    buttonPosRef.current = buttonPos;
  }, [buttonPos]);

  useEffect(() => {
    panelPosRef.current = panelPos;
  }, [panelPos]);

  useEffect(() => {
    scaleRef.current = scale;
  }, [scale]);

  useEffect(() => {
    openRef.current = open;
  }, [open]);

  useEffect(() => {
    closeOnOutsideRef.current = closeOnOutside;
  }, [closeOnOutside]);

  const currentPanelSize = useCallback(
    (nextScale = scaleRef.current) => panelSize(nextScale, closeOnOutsideRef.current, tabletRef.current.open),
    [],
  );

  const finishDrag = useCallback(() => {
    const drag = dragRef.current;
    if (!drag) return;
    dragRef.current = null;
    if (drag.mode === 'resize-nw' || drag.mode === 'resize-se') {
      saveScale(scaleRef.current);
      savePosition(PANEL_POS_KEY, panelPosRef.current);
      return;
    }
    if (drag.mode === 'panel') {
      savePosition(PANEL_POS_KEY, panelPosRef.current);
      return;
    }
    savePosition(BUTTON_POS_KEY, buttonPosRef.current);
    if (!drag.moved) {
      setOpen(true);
    }
  }, []);

  const handleDragMove = useCallback((event: PointerEvent) => {
    const drag = dragRef.current;
    if (!drag) return;
    const point = toParentPoint(event);
    const dx = point.x - drag.startX;
    const dy = point.y - drag.startY;
    if (Math.abs(dx) > 4 || Math.abs(dy) > 4) {
      drag.moved = true;
    }
    if (drag.mode === 'resize-nw' || drag.mode === 'resize-se') {
      const baseWidth = PHONE_WIDTH + (tabletRef.current.open ? TABLET_WIDTH + TABLET_GAP : 0);
      const projectedWidth =
        drag.mode === 'resize-se' ? baseWidth * drag.originScale + dx : baseWidth * drag.originScale - dx;
      const projectedHeight =
        drag.mode === 'resize-se' ? PHONE_HEIGHT * drag.originScale + dy : PHONE_HEIGHT * drag.originScale - dy;
      const nextScale = clampScale(Math.min(projectedWidth / baseWidth, projectedHeight / PHONE_HEIGHT));
      const size = panelSize(nextScale, closeOnOutsideRef.current, tabletRef.current.open);
      const nextPos =
        drag.mode === 'resize-se'
          ? clampPosition({ x: drag.originX, y: drag.originY }, size.width, size.height)
          : clampPosition({ x: drag.anchorX - size.width, y: drag.anchorY - size.height }, size.width, size.height);
      scaleRef.current = nextScale;
      panelPosRef.current = nextPos;
      setScale(nextScale);
      setPanelPos(nextPos);
      applyFrameStyle(true, nextPos, nextScale, closeOnOutsideRef.current, tabletRef.current.open);
      return;
    }
    const size =
      drag.mode === 'panel'
        ? panelSize(scaleRef.current, closeOnOutsideRef.current, tabletRef.current.open)
        : { width: BUTTON_SIZE, height: BUTTON_SIZE };
    const next = clampPosition({ x: drag.originX + dx, y: drag.originY + dy }, size.width, size.height);
    if (drag.mode === 'panel') {
      panelPosRef.current = next;
      setPanelPos(next);
      applyFrameStyle(true, next, scaleRef.current, closeOnOutsideRef.current, tabletRef.current.open);
      return;
    }
    buttonPosRef.current = next;
    setButtonPos(next);
    applyFrameStyle(false, next);
  }, []);

  const handleDragEnd = useCallback(() => {
    window.removeEventListener('pointermove', handleDragMove);
    window.removeEventListener('pointerup', handleDragEnd);
    window.removeEventListener('pointercancel', handleDragEnd);
    getParentWindow().removeEventListener('pointermove', handleDragMove);
    getParentWindow().removeEventListener('pointerup', handleDragEnd);
    getParentWindow().removeEventListener('pointercancel', handleDragEnd);
    finishDrag();
  }, [finishDrag, handleDragMove]);

  const beginDrag = (event: React.PointerEvent, mode: DragMode) => {
    event.preventDefault();
    event.stopPropagation();
    const point = toParentPoint(event);
    const origin = mode === 'button' ? buttonPosRef.current : panelPosRef.current;
    const size = panelSize(scaleRef.current, closeOnOutsideRef.current, tabletRef.current.open);
    dragRef.current = {
      startX: point.x,
      startY: point.y,
      originX: origin.x,
      originY: origin.y,
      originScale: scaleRef.current,
      moved: false,
      mode,
      anchorX: origin.x + size.width,
      anchorY: origin.y + size.height,
    };
    window.addEventListener('pointermove', handleDragMove);
    window.addEventListener('pointerup', handleDragEnd);
    window.addEventListener('pointercancel', handleDragEnd);
    getParentWindow().addEventListener('pointermove', handleDragMove);
    getParentWindow().addEventListener('pointerup', handleDragEnd);
    getParentWindow().addEventListener('pointercancel', handleDragEnd);
  };

  useEffect(() => {
    if (scriptMounted) {
      setActive(true);
      return;
    }
    const syncActive = () => {
      const latest = isLatestFloor();
      setActive(latest);
      if (!latest) {
        setOpen(false);
        autoOpenedRef.current = false;
        return;
      }
      if (getLatestFloor() === 0 && !autoOpenedRef.current) {
        autoOpenedRef.current = true;
        setOpen(true);
      }
    };
    syncActive();
    const timer = window.setInterval(syncActive, 800);
    [
      tavern_events.MESSAGE_RECEIVED,
      tavern_events.MESSAGE_SENT,
      tavern_events.CHARACTER_MESSAGE_RENDERED,
      tavern_events.USER_MESSAGE_RENDERED,
      tavern_events.CHAT_CHANGED,
      tavern_events.MESSAGE_DELETED,
    ].forEach(eventType => eventOn(eventType, syncActive));
    return () => window.clearInterval(timer);
  }, [scriptMounted]);

  useEffect(() => {
    if (!active) {
      if (!scriptMounted) {
        restoreCampusFrame();
        hideFrameInChat();
      }
      return;
    }
    mountFrameToHost();
    applyFrameStyle(open, open ? panelPos : buttonPos, scale, closeOnOutside, tablet.open);
  }, [active, open, buttonPos, panelPos, scale, scriptMounted, closeOnOutside, tablet.open]);

  useEffect(() => {
    const onResize = () => {
      if (tabletRef.current.open) {
        const viewport = getParentWindow();
        const fit = Math.min(
          scaleRef.current,
          Math.max(
            0.2,
            (viewport.innerWidth - HANDLE_PAD * 2 - OUTER_CONTROL_GAP - 16) / (PHONE_WIDTH + TABLET_WIDTH + TABLET_GAP),
          ),
          Math.max(
            0.2,
            (viewport.innerHeight - HANDLE_PAD * 2 - (closeOnOutsideRef.current ? 0 : CLOSE_GAP + CLOSE_HEIGHT) - 16) /
              PHONE_HEIGHT,
          ),
        );
        scaleRef.current = fit;
        setScale(fit);
      }
      const size = currentPanelSize();
      const nextButton = clampPosition(buttonPosRef.current, BUTTON_SIZE, BUTTON_SIZE);
      const nextPanel = clampPosition(panelPosRef.current, size.width, size.height);
      buttonPosRef.current = nextButton;
      panelPosRef.current = nextPanel;
      setButtonPos(nextButton);
      setPanelPos(nextPanel);
    };
    onResize();
    getParentWindow().addEventListener('resize', onResize);
    return () => getParentWindow().removeEventListener('resize', onResize);
  }, [currentPanelSize]);

  useEffect(() => {
    if (!open || !closeOnOutside || !active) return;

    const isPhoneTarget = (target: EventTarget | null) => {
      const node = target as Node | null;
      const el = target as HTMLElement | null;
      if (el?.closest?.('[data-phone-handle="true"], .campus-tablet')) return true;
      const phone = document.querySelector('.phone-frame');
      return Boolean(phone && node && phone.contains(node));
    };

    const onLocalPointerDown = (event: PointerEvent) => {
      if (dragRef.current || !openRef.current || !closeOnOutsideRef.current) return;
      if (isPhoneTarget(event.target)) return;
      setOpen(false);
    };

    const onParentPointerDown = (event: PointerEvent) => {
      if (dragRef.current || !openRef.current || !closeOnOutsideRef.current) return;
      const frame = getFrame();
      const node = event.target as Node | null;
      if (frame && node && (node === frame || frame.contains(node))) return;
      setOpen(false);
    };

    window.addEventListener('pointerdown', onLocalPointerDown, true);
    getParentWindow().addEventListener('pointerdown', onParentPointerDown, true);
    return () => {
      window.removeEventListener('pointerdown', onLocalPointerDown, true);
      getParentWindow().removeEventListener('pointerdown', onParentPointerDown, true);
    };
  }, [active, open, closeOnOutside]);

  useEffect(() => () => restoreCampusFrame(), []);

  if (!active) {
    return null;
  }

  if (!open) {
    return (
      <button
        type="button"
        onPointerDown={event => beginDrag(event, 'button')}
        className="relative w-full h-full rounded-full accent-btn flex flex-col items-center justify-center select-none cursor-grab active:cursor-grabbing touch-none"
        title={forumGenerating ? '论坛生成中，点击打开校园手机' : '打开校园手机'}
      >
        {forumGenerating && (
          <span
            role="status"
            className="pointer-events-none absolute right-1 top-2 whitespace-nowrap rounded-full bg-rose-500 px-1.5 py-0.5 text-[9px] font-bold leading-tight text-white shadow-sm"
          >
            生成中
          </span>
        )}
        <Smartphone className="w-7 h-7" strokeWidth={2.2} />
        <span className="text-[10px] font-bold mt-0.5 tracking-wide">手机</span>
      </button>
    );
  }

  const scaledPhoneWidth = PHONE_WIDTH * scale;
  const scaledPhoneHeight = PHONE_HEIGHT * scale;
  const dockWidth = (PHONE_WIDTH + (tablet.open ? TABLET_WIDTH + TABLET_GAP : 0)) * scale;
  const phoneOffset = tablet.open && tablet.side === 'left' ? (TABLET_WIDTH + TABLET_GAP) * scale : 0;

  return (
    <div className="relative w-full h-full bg-transparent" style={{ padding: HANDLE_PAD }}>
      <div
        data-phone-handle="true"
        className="absolute z-[80] pointer-events-auto cursor-nwse-resize touch-none"
        style={{ left: 0, top: 0, width: HANDLE_PAD + 8, height: HANDLE_PAD + 8 }}
        onPointerDown={event => beginDrag(event, 'resize-nw')}
        title="等比例缩放"
      >
        <ScaleHandle corner="nw" />
      </div>
      <div
        data-phone-handle="true"
        className="absolute z-[80] pointer-events-auto cursor-nwse-resize touch-none"
        style={{
          right: 0,
          bottom: closeOnOutside ? 0 : CLOSE_GAP + CLOSE_HEIGHT,
          width: HANDLE_PAD + 8,
          height: HANDLE_PAD + 8,
        }}
        onPointerDown={event => beginDrag(event, 'resize-se')}
        title="等比例缩放"
      >
        <ScaleHandle corner="se" />
      </div>
      <div className="relative mx-auto" style={{ width: dockWidth, height: scaledPhoneHeight, pointerEvents: 'none' }}>
        {tablet.open && (
          <div
            className="absolute top-0 campus-tablet-dock"
            style={{
              left: tablet.side === 'left' ? 0 : scaledPhoneWidth + TABLET_GAP * scale,
              width: TABLET_WIDTH * scale,
              height: scaledPhoneHeight,
              pointerEvents: 'auto',
            }}
          >
            <div
              className="origin-top-left"
              style={{ width: TABLET_WIDTH, height: PHONE_HEIGHT, transform: `scale(${scale})` }}
            >
              <CampusTablet
                onFlip={() => changeTablet({ ...tablet, side: tablet.side === 'left' ? 'right' : 'left' })}
              />
            </div>
          </div>
        )}
        <div
          className="absolute top-0 origin-top-left phone-panel"
          style={{
            left: phoneOffset,
            width: PHONE_WIDTH,
            height: PHONE_HEIGHT,
            transform: `scale(${scale})`,
            pointerEvents: 'auto',
          }}
        >
          <div className="absolute inset-0 overflow-visible">{children}</div>
        </div>
        {tablet.open && (
          <div
            data-phone-handle="true"
            className="absolute z-[90] pointer-events-auto"
            style={{ left: phoneOffset + scaledPhoneWidth - 8, top: -HANDLE_PAD + 6 }}
          >
            <div className="campus-tablet-connector">
              <button
                type="button"
                onClick={() => changeTablet({ ...tablet, side: tablet.side === 'left' ? 'right' : 'left' })}
                title="切换展开方向"
                aria-label="切换展开方向"
              >
                <ArrowLeftRight size={13} />
              </button>
              <button
                type="button"
                onClick={() => changeTablet({ ...tablet, open: false })}
                title="收起平板"
                aria-label="收起平板"
              >
                <X size={16} />
              </button>
            </div>
          </div>
        )}
        {!tablet.open && (
          <div
            data-phone-handle="true"
            className="absolute z-[90] pointer-events-auto"
            style={{ left: phoneOffset + scaledPhoneWidth - 8, top: -HANDLE_PAD + 6 }}
          >
            <div className="campus-tablet-connector">
              <button
                type="button"
                onClick={() => changeTablet({ ...tablet, open: true })}
                title="展开平板"
                aria-label="展开平板"
              >
                <NotebookPen size={16} />
              </button>
            </div>
          </div>
        )}
        <div
          data-phone-handle="true"
          className="absolute top-0 origin-top-left pointer-events-none"
          style={{ left: phoneOffset - 2 * scale, width: PHONE_WIDTH * scale + 4 * scale, height: scaledPhoneHeight }}
        >
          <div className="absolute inset-0 z-[70] pointer-events-none rounded-[48px]">
            <div
              className="absolute inset-x-0 top-0 pointer-events-auto cursor-grab active:cursor-grabbing touch-none"
              style={{ height: EDGE }}
              onPointerDown={event => beginDrag(event, 'panel')}
            />
            <div
              className="absolute inset-x-0 bottom-0 pointer-events-auto cursor-grab active:cursor-grabbing touch-none"
              style={{ height: EDGE }}
              onPointerDown={event => beginDrag(event, 'panel')}
            />
            <div
              className="absolute inset-y-0 left-0 pointer-events-auto cursor-grab active:cursor-grabbing touch-none"
              style={{ width: EDGE }}
              onPointerDown={event => beginDrag(event, 'panel')}
            />
            <div
              className="absolute inset-y-0 right-0 pointer-events-auto cursor-grab active:cursor-grabbing touch-none"
              style={{ width: EDGE }}
              onPointerDown={event => beginDrag(event, 'panel')}
            />
          </div>
        </div>
      </div>
      {!closeOnOutside && (
        <button
          type="button"
          onClick={() => setOpen(false)}
          className="mx-auto mt-2.5 px-4 rounded-full bg-black/70 hover:bg-black/80 text-white text-xs font-bold flex items-center justify-center gap-1.5 shadow-lg"
          style={{ height: CLOSE_HEIGHT }}
        >
          <X className="w-3.5 h-3.5" />
          关闭
        </button>
      )}
    </div>
  );
}
