import type { CampusLocationData } from './campusLocations';

type BuildingDef = Partial<CampusLocationData> & {
  X坐标: number; Y坐标: number; 宽度: number; 高度: number;
  建筑类型: '餐饮娱乐' | '学习设施' | '运动设施' | '宿舍生活' | '自然环境';
  建筑描述: string; 建筑活动: any[];
};

function locations(groups: Array<[string, string[]]>, type = '公共设施'): CampusLocationData {
  return {
    分区: groups.map(([名称], index) => ({ 名称, 类型: /层|楼/.test(名称) ? '楼层' : '区域', 排序: index + 1 })),
    地点: groups.flatMap(([所属分区, names]) => names.map(名称 => ({ 名称, 所属分区, 类型: type, 描述: '', 状态: '开放' as const, 剧情重要: true, 发现状态: '已知' as const }))),
  };
}

const classroomLocations = () => locations([
  ['一层', ['教师休息区', '自习室']], ['二层', ['厕所']], ['三层', []], ['顶楼', ['天台']],
]);

