import { useEffect, useRef, useState } from 'react';
import { Check, ChevronDown } from 'lucide-react';

type Option = { value: number; label: string };

export function FrequencySelect({ value, options, onChange }: { value: number; options: Option[]; onChange: (value: number) => void }) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const closeOnOutside = (event: PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false);
    };
    const closeOnKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setOpen(false);
    };
    document.addEventListener('pointerdown', closeOnOutside);
    document.addEventListener('keydown', closeOnKey);
    return () => {
      document.removeEventListener('pointerdown', closeOnOutside);
      document.removeEventListener('keydown', closeOnKey);
    };
  }, []);

  const selected = options.find(option => option.value === value) || options[0];
  return (
    <div className="relative" ref={rootRef}>
      <button type="button" aria-haspopup="listbox" aria-expanded={open} onClick={() => setOpen(current => !current)} className="flex h-9 min-w-[132px] items-center justify-between gap-3 rounded-xl border border-border-default bg-surface-solid px-3 text-xs font-semibold text-text-primary shadow-sm hover-fill">
        <span>{selected.label}</span><ChevronDown className={`h-3.5 w-3.5 text-text-secondary transition-transform ${open ? 'rotate-180' : ''}`} />
      </button>
      {open && <div role="listbox" className="absolute right-0 top-full z-50 mt-2 w-full min-w-[148px] overflow-hidden rounded-xl border border-border-default bg-surface-solid p-1 shadow-xl">
        {options.map(option => <button key={option.value} type="button" role="option" aria-selected={option.value === value} onClick={() => { onChange(option.value); setOpen(false); }} className={`flex h-9 w-full items-center justify-between rounded-lg px-2.5 text-left text-xs transition-colors ${option.value === value ? 'bg-[color:var(--action-text)]/10 font-bold text-[color:var(--action-text)]' : 'text-text-primary hover:bg-surface'}`}>
          <span>{option.label}</span>{option.value === value && <Check className="h-3.5 w-3.5" />}
        </button>)}
      </div>}
    </div>
  );
}
