import { ChevronLeft, Pencil, Plus, Search } from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';
import { ConfirmDialog } from '../状态栏/src/components/ui/ConfirmDialog';
import { CenterModal, FullScreenModal } from '../状态栏/src/components/ui/Modal';
import { useDraggableScroll } from '../状态栏/src/hooks/useDraggableScroll';
import {
  buildClassmateEntryName,
  ClassmateArchive,
  emptyRoleArchiveForm,
  loadAllClassmateArchives,
  parseClassmateProfile,
  parseRoleArchiveForm,
  parseRoleArchiveName,
  RoleArchiveForm,
  serializeRoleArchiveForm,
} from './classmates';
import { ClassmateDetailView } from './ClassmateDetailView';
import { RoleArchiveFormFields } from './RoleArchiveForm';

interface ClassmateSelectorProps {
  campusType: string;
  selectedNames: string[];
  edits: Record<string, string>;
  customClassmates: { name: string; content: string }[];
  onChange: (payload: {
    selectedNames: string[];
    edits: Record<string, string>;
    customClassmates: { name: string; content: string }[];
  }) => void;
}

const CROSS_TYPE_SKIP_KEY = 'campus-app-classmate-cross-type-skip';

function loadSkippedCampusTypes(): Set<string> {
  try {
    const raw = window.localStorage.getItem(CROSS_TYPE_SKIP_KEY);
    const list = raw ? (JSON.parse(raw) as string[]) : [];
    return new Set(Array.isArray(list) ? list.filter(item => typeof item === 'string' && item.trim()) : []);
  } catch {
    return new Set();
  }
}

function saveSkippedCampusTypes(types: Set<string>) {
  try {
    window.localStorage.setItem(CROSS_TYPE_SKIP_KEY, JSON.stringify([...types]));
  } catch {
    // ignore
  }
}

export function ClassmateSelector({
  campusType,
  selectedNames,
  edits,
  customClassmates,
  onChange,
}: ClassmateSelectorProps) {
  const [worldbookClassmates, setWorldbookClassmates] = useState<ClassmateArchive[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewing, setViewing] = useState<ClassmateArchive | null>(null);
  const [editing, setEditing] = useState(false);
  const [draftForm, setDraftForm] = useState<RoleArchiveForm>(() => emptyRoleArchiveForm());
  const [creating, setCreating] = useState(false);
  const [createForm, setCreateForm] = useState<RoleArchiveForm>(() => emptyRoleArchiveForm());
  const [pendingSelect, setPendingSelect] = useState<ClassmateArchive | null>(null);
  const [skipChecked, setSkipChecked] = useState(false);
  const [skippedTypes, setSkippedTypes] = useState<Set<string>>(() => loadSkippedCampusTypes());
  const detailScroll = useDraggableScroll<HTMLDivElement>();

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    loadAllClassmateArchives()
      .then(list => {
        if (!cancelled) setWorldbookClassmates(list);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const classmates = useMemo(() => {
    const fromWorld = worldbookClassmates.map(item =>
      parseClassmateProfile(item.name, edits[item.name] ?? item.content, false, item.uid),
    );
    const fromCustom = customClassmates
      .filter(item => !fromWorld.some(existing => existing.name === item.name))
      .map(item => parseClassmateProfile(item.name, edits[item.name] ?? item.content, true));
    return [...fromWorld, ...fromCustom].sort((a, b) => {
      const typeCmp = a.campusType.localeCompare(b.campusType, 'zh-CN');
      if (typeCmp !== 0) return typeCmp;
      return a.displayName.localeCompare(b.displayName, 'zh-CN');
    });
  }, [worldbookClassmates, customClassmates, edits]);

  const viewingForm = viewing
    ? parseRoleArchiveForm(
        edits[viewing.name] ?? viewing.content,
        parseRoleArchiveName(viewing.name)?.character || viewing.displayName,
      )
    : emptyRoleArchiveForm();

  const applySelect = (name: string) => {
    const next = selectedNames.includes(name)
      ? selectedNames.filter(item => item !== name)
      : [...selectedNames, name];
    onChange({ selectedNames: next, edits, customClassmates });
  };

  const toggle = (item: ClassmateArchive) => {
    if (selectedNames.includes(item.name)) {
      applySelect(item.name);
      return;
    }
    const isCrossType = Boolean(item.campusType) && item.campusType !== campusType;
    if (isCrossType && !skippedTypes.has(item.campusType)) {
      setSkipChecked(false);
      setPendingSelect(item);
      return;
    }
    applySelect(item.name);
  };

  const confirmCrossTypeSelect = () => {
    if (!pendingSelect) return;
    if (skipChecked) {
      const next = new Set(skippedTypes);
      next.add(pendingSelect.campusType);
      setSkippedTypes(next);
      saveSkippedCampusTypes(next);
    }
    applySelect(pendingSelect.name);
    setPendingSelect(null);
  };

  const openView = (item: ClassmateArchive) => {
    const parsed = parseRoleArchiveName(item.name);
    setViewing(item);
    setEditing(false);
    setDraftForm(parseRoleArchiveForm(edits[item.name] ?? item.content, parsed?.character || item.displayName));
  };

  const saveEdit = () => {
    if (!viewing) return;
    const content = serializeRoleArchiveForm(draftForm);
    onChange({
      selectedNames,
      edits: { ...edits, [viewing.name]: content },
      customClassmates: customClassmates.map(item =>
        item.name === viewing.name ? { ...item, content } : item,
      ),
    });
    setViewing(parseClassmateProfile(viewing.name, content, viewing.custom, viewing.uid));
    setEditing(false);
  };

  const openCreate = () => {
    setCreateForm(emptyRoleArchiveForm());
    setCreating(true);
  };

  const saveCreate = () => {
    const character = createForm.name.trim();
    if (!character) return;
    const entryName = buildClassmateEntryName(character, campusType);
    if (classmates.some(item => item.name === entryName)) return;
    const content = serializeRoleArchiveForm(createForm);
    onChange({
      selectedNames: [...selectedNames, entryName],
      edits: { ...edits, [entryName]: content },
      customClassmates: [...customClassmates, { name: entryName, content }],
    });
    setCreating(false);
  };

  return (
    <div className="space-y-2">
      {loading && <p className="text-xs text-text-secondary px-1">正在读取世界书中的角色档案…</p>}
      {!loading && classmates.length === 0 && (
        <p className="text-xs text-text-secondary rounded-2xl border border-dashed border-border-default bg-surface p-3">
          还没有可实装的角色档案。
        </p>
      )}
      {classmates.map(item => {
        const selected = selectedNames.includes(item.name);
        const mismatched = Boolean(item.campusType) && item.campusType !== campusType;
        return (
          <div
            key={item.name}
            className={`relative rounded-2xl px-3.5 py-3 transition-all ${
              selected ? 'theme-selected shadow-sm' : 'theme-option'
            }`}
          >
            {item.campusType ? (
              <span
                className={`absolute top-2 right-2 max-w-[46%] truncate text-[10px] font-bold px-1.5 py-0.5 rounded-full border ${
                  mismatched
                    ? 'bg-amber-50 text-amber-600 border-amber-200'
                    : 'theme-selected'
                }`}
                title={item.campusType}
              >
                {item.campusType}
              </span>
            ) : null}
            <button type="button" onClick={() => toggle(item)} className="w-full text-left pr-10">
              <div className="flex items-center gap-2 min-w-0">
                <span
                  className={`w-4 h-4 rounded-md border flex items-center justify-center shrink-0 ${
                    selected ? 'theme-mark' : 'border-border-default bg-surface-solid'
                  }`}
                >
                  {selected ? <span className="w-1.5 h-1.5 rounded-sm bg-white" /> : null}
                </span>
                <span className={`text-sm font-bold truncate ${selected ? 'text-selected-text' : 'text-text-primary'}`}>
                  {item.displayName}
                </span>
                {item.custom ? (
                  <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full theme-custom-tag">
                    自定义
                  </span>
                ) : null}
              </div>
              <p className="mt-2 text-xs leading-5 text-text-secondary pl-6 pr-8">
                {item.age} · {item.gender} · {item.identity} · {item.relation}
              </p>
            </button>
            <button
              type="button"
              onClick={() => openView(item)}
              className="absolute bottom-2.5 right-2.5 w-8 h-8 rounded-full bg-surface text-text-secondary flex items-center justify-center"
              title="查看详情"
            >
              <Search className="w-4 h-4" />
            </button>
          </div>
        );
      })}

      <button
        type="button"
        onClick={openCreate}
        className="w-full py-2.5 rounded-2xl theme-dashed-btn font-bold text-sm flex items-center justify-center gap-1"
      >
        <Plus className="w-4 h-4" />
        新建自定义角色
      </button>

      <ConfirmDialog
        open={Boolean(pendingSelect)}
        title="跨校园类型确认"
        message={
          pendingSelect
            ? `「${pendingSelect.displayName}」属于「${pendingSelect.campusType}」，与当前校园类型「${campusType}」不同。确定要实装这个角色吗？`
            : ''
        }
        confirmText="确认选择"
        onClose={() => setPendingSelect(null)}
        onConfirm={confirmCrossTypeSelect}
      >
        <label className="mt-3 flex items-center gap-2 text-xs text-text-secondary">
          <input
            type="checkbox"
            checked={skipChecked}
            onChange={event => setSkipChecked(event.target.checked)}
            className="w-3.5 h-3.5 rounded border-border-default accent-[var(--selected-mark)]"
          />
          不再提醒「{pendingSelect?.campusType || ''}」类型
        </label>
      </ConfirmDialog>

      <FullScreenModal isOpen={Boolean(viewing)} className="z-30 pt-12 glass">
        {viewing ? (
          <div className="relative flex-1 min-h-0 flex flex-col">
            <div className="px-4 pb-3 flex items-center justify-between">
              <button
                type="button"
                onClick={() => setViewing(null)}
                className="w-9 h-9 rounded-full bg-surface-solid border border-border-default flex items-center justify-center text-text-primary"
                title="返回"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>
              <button
                type="button"
                onClick={() => {
                  setDraftForm(viewingForm);
                  setEditing(true);
                }}
                className="w-9 h-9 rounded-full bg-surface-solid border border-border-default flex items-center justify-center text-[color:var(--action-text)]"
                title="编辑档案"
              >
                <Pencil className="w-4 h-4" />
              </button>
            </div>
            <div
              className="flex-1 min-h-0 overflow-y-auto overflow-x-hidden hide-scrollbar pb-8 px-4"
              {...detailScroll}
              ref={detailScroll.ref}
            >
              <ClassmateDetailView form={viewingForm} />
            </div>
          </div>
        ) : null}
      </FullScreenModal>

      <CenterModal
        isOpen={editing}
        onClose={() => setEditing(false)}
        className="glass w-[calc(100%-2rem)] max-w-[300px] min-w-0 h-[80vh] max-h-[80vh] rounded-[20px] shadow-xl p-0 box-border"
      >
        <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden p-4 hide-scrollbar overscroll-contain touch-pan-y">
          <h3 className="text-base font-bold text-text-primary mb-3">编辑角色档案</h3>
          <RoleArchiveFormFields form={draftForm} onChange={setDraftForm} />
          <div className="flex gap-2 mt-4">
            <button
              type="button"
              onClick={() => setEditing(false)}
              className="flex-1 py-2.5 text-sm font-bold rounded-xl bg-surface-solid border border-border-default text-text-secondary"
            >
              取消
            </button>
            <button
              type="button"
              onClick={saveEdit}
              className="flex-1 py-2.5 text-sm font-bold rounded-xl accent-btn"
            >
              保存
            </button>
          </div>
        </div>
      </CenterModal>

      <CenterModal
        isOpen={creating}
        onClose={() => setCreating(false)}
        className="glass w-[calc(100%-2rem)] max-w-[300px] min-w-0 h-[80vh] max-h-[80vh] rounded-[20px] shadow-xl p-0 box-border"
      >
        <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden p-4 hide-scrollbar overscroll-contain touch-pan-y">
          <h3 className="text-base font-bold text-text-primary mb-3">新建自定义角色</h3>
          <RoleArchiveFormFields form={createForm} onChange={setCreateForm} />
          <div className="flex gap-2">
            <button
              type="button"
              onClick={() => setCreating(false)}
              className="flex-1 py-2.5 text-sm font-bold rounded-xl bg-surface-solid border border-border-default text-text-secondary"
            >
              取消
            </button>
            <button
              type="button"
              disabled={!createForm.name.trim()}
              onClick={saveCreate}
              className="flex-1 py-2.5 text-sm font-bold rounded-xl accent-btn disabled:opacity-50"
            >
              保存
            </button>
          </div>
        </div>
      </CenterModal>
    </div>
  );
}
