import { useEffect } from 'react';
import { generateForumPosts, getForumChatId, getLatestAssistantMessageId, isForumGenerating, markForumReplyForRetry, markForumReplyProcessed, readForumGenerationConfig, readForumState } from '../utils/forumGeneration';

export function useForumAutoGeneration() {
  useEffect(() => {
    let timer: number | undefined;
    let disposed = false;
    let pending = false;
    const run = async () => {
      if (disposed) return;
      try {
        const config = readForumGenerationConfig();
        if (!config.enabled) return;
        if (isForumGenerating()) { pending = true; return; }
        const id = getLatestAssistantMessageId();
        if (id < 0 || id <= readForumState().processedMessageId) return;
        const previous = readForumState();
        const next = markForumReplyProcessed(id);
        if (previous.lastGeneratedAt || previous.records?.some(record => record.status === 'success')) {
          if (next.replyCount % config.everyReplies !== 0) return;
        }
        const chatId = getForumChatId();
        try { await generateForumPosts(); }
        catch { markForumReplyForRetry(id); /* The service stores a safe error for the retry UI. */ }
        if (!disposed && getForumChatId() === chatId && pending) { pending = false; schedule(); }
      } catch (error) { console.warn('[校园论坛] 自动触发失败', error); }
    };
    const schedule = () => { window.clearTimeout(timer); timer = window.setTimeout(() => void run(), 500); };
    const subscriptions: EventOnReturn[] = [];
    if (typeof eventOn === 'function') {
      subscriptions.push(eventOn(tavern_events.MESSAGE_RECEIVED, schedule));
      subscriptions.push(eventOn(tavern_events.MESSAGE_UPDATED, schedule));
      subscriptions.push(eventOn(tavern_events.CHAT_CHANGED, () => { window.clearTimeout(timer); pending = false; }));
    }
    return () => { disposed = true; window.clearTimeout(timer); subscriptions.forEach(subscription => subscription.stop()); };
  }, []);
}
