import { useCallback, useEffect, useState } from 'react';
import { applyCampusAppUpdate, checkCampusAppUpdate, UpdateCheckResult } from '../utils/runtimeVersion';

let snapshot: UpdateCheckResult | null = null;
let inflight: Promise<UpdateCheckResult> | null = null;
const listeners = new Set<() => void>();

function emit() {
  listeners.forEach(listener => listener());
}

export async function refreshCampusUpdate(force = false): Promise<UpdateCheckResult> {
  if (!force && snapshot) return snapshot;
  if (inflight) return inflight;
  inflight = checkCampusAppUpdate()
    .then(next => {
      snapshot = next;
      inflight = null;
      emit();
      return next;
    })
    .catch(error => {
      inflight = null;
      throw error;
    });
  return inflight;
}

export function useCampusUpdate() {
  const [result, setResult] = useState<UpdateCheckResult | null>(snapshot);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    const listener = () => setResult(snapshot);
    listeners.add(listener);
    void refreshCampusUpdate();
    return () => {
      listeners.delete(listener);
    };
  }, []);

  const refresh = useCallback(async () => {
    setBusy(true);
    try {
      return await refreshCampusUpdate(true);
    } finally {
      setBusy(false);
    }
  }, []);

  const applyUpdate = useCallback(async () => {
    setBusy(true);
    try {
      await applyCampusAppUpdate();
    } finally {
      setBusy(false);
    }
  }, []);

  return {
    result,
    busy,
    hasUpdate: Boolean(result?.hasUpdate),
    refresh,
    applyUpdate,
  };
}
