export const FORUM_STATE_PATH = '校园APP.论坛';
export const FORUM_GENERATE_EVENT = 'campus-forum-generate';
export const FORUM_STATE_EVENT = 'campus-forum-state-changed';
export type ForumGenerationConfig = {
  enabled: boolean;
  everyReplies: number;
  apiSource: 'tavern' | 'custom';
  apiUrl: string;
  apiKey: string;
  model: string;
  temperature: number;
  maxTokens: number;
  postCount: number;
  timeoutSeconds: number;
  categories: ForumCategory[];
};
export type ForumGenerationRecord = {
  id: string;
  startedAt: number;
  durationMs: number;
  status: 'success' | 'error' | 'cancelled' | 'timeout';
  model: string;
  newPosts: number;
  newReplies: number;
  error?: string;
  content?: string;
};
export class ForumGenerationError extends Error {
  readonly rawContent?: string;
  constructor(message: string, rawContent?: string) {
    super(message);
    this.name = 'ForumGenerationError';
    this.rawContent = rawContent?.slice(0, 30000);
  }
}
export type ForumState = {
  posts: ForumPost[];
  processedMessageId: number;
  replyCount: number;
  lastGeneratedAt: number;
  lastError?: string;
  promptSource?: string;
  initialized?: boolean;
  unreadPostIds?: string[];
  records?: ForumGenerationRecord[];
};
const DEFAULT_CONFIG: ForumGenerationConfig = {
  enabled: true,
  everyReplies: 2,
  apiSource: 'tavern',
  apiUrl: '',
  apiKey: '',
  model: '',
  temperature: 0.8,
  maxTokens: 2048,
  postCount: 3,
  timeoutSeconds: 120,
  categories: DEFAULT_FORUM_CATEGORIES,
};
const CONFIG_KEY = 'campus-app-forum-generation-config';
type ActiveGeneration = {
  promise: Promise<ForumState>;
  id: string;
  reason?: 'cancelled' | 'timeout';
  cancel: (reason: 'cancelled' | 'timeout') => void;
};
const active = new Map<string, ActiveGeneration>();
function bounded(value: unknown, fallback: number, min: number, max: number): number {
  const number = Number(value);
  return value == null || !Number.isFinite(number) ? fallback : Math.min(max, Math.max(min, number));
}
export function getForumChatId(): string {
  const variables = getVariables({ type: 'chat' });
  const existing = _.get(variables, `${FORUM_STATE_PATH}.chatId`);
  if (typeof existing === 'string' && existing) return existing;
  const id = crypto.randomUUID();
  updateVariablesWith(
    current => {
      _.set(current, `${FORUM_STATE_PATH}.chatId`, id);
      return current;
    },
    { type: 'chat' },
  );
  return id;
}
export function readForumState(): ForumState {
  let stored: Partial<ForumState> = {};
  try {
    stored = _.get(getVariables({ type: 'chat' }), FORUM_STATE_PATH) || {};
  } catch {
    /* Host may still be mounting. */
  }
  return {
    posts: Array.isArray(stored.posts) ? stored.posts.filter(post => post && typeof post.id === 'string') : [],
    processedMessageId: bounded(stored.processedMessageId, -1, -1, Number.MAX_SAFE_INTEGER),
    replyCount: bounded(stored.replyCount, 0, 0, Number.MAX_SAFE_INTEGER),
    lastGeneratedAt: bounded(stored.lastGeneratedAt, 0, 0, Number.MAX_SAFE_INTEGER),
    lastError: typeof stored.lastError === 'string' ? stored.lastError : undefined,
    promptSource: typeof stored.promptSource === 'string' ? stored.promptSource : undefined,
    initialized: stored.initialized === true,
    unreadPostIds: Array.isArray(stored.unreadPostIds)
      ? stored.unreadPostIds.filter((id): id is string => typeof id === 'string')
      : [],
    records: Array.isArray(stored.records) ? stored.records.slice(0, 20) : [],
  };
}
export function saveForumState(state: ForumState): void {
  updateVariablesWith(
    variables => {
      const previous = _.get(variables, FORUM_STATE_PATH) || {};
      _.set(variables, FORUM_STATE_PATH, { ...previous, ...state, schemaVersion: 2 });
      return variables;
    },
    { type: 'chat' },
  );
  window.dispatchEvent(new CustomEvent(FORUM_STATE_EVENT));
}
export function isForumGenerating(): boolean {
  try {
    return active.has(getForumChatId());
  } catch {
    return false;
  }
}
export function readForumGenerationConfig(): ForumGenerationConfig {
  try {
    const value = JSON.parse(window.localStorage.getItem(CONFIG_KEY) || '{}') || {};
    return {
      enabled: value.enabled !== false,
      everyReplies: Math.round(bounded(value.everyReplies, 2, 1, 10)),
      apiSource: value.apiSource === 'custom' ? 'custom' : 'tavern',
      apiUrl: typeof value.apiUrl === 'string' ? value.apiUrl : '',
      apiKey: typeof value.apiKey === 'string' ? value.apiKey : '',
      model: typeof value.model === 'string' ? value.model : '',
      temperature: bounded(value.temperature, 0.8, 0, 2),
      maxTokens: Math.round(bounded(value.maxTokens, 2048, 64, 32768)),
      postCount: Math.round(bounded(value.postCount, 3, 1, 5)),
      timeoutSeconds: Math.round(bounded(value.timeoutSeconds, 120, 30, 300)),
      categories: Array.isArray(value.categories)
        ? normalizeForumCategories(value.categories).map(category => {
            const defaultCategory = DEFAULT_FORUM_CATEGORIES.find(item => item.id === category.id);
            return !category.description.trim() && defaultCategory
              ? { ...category, description: defaultCategory.description }
              : category;
          })
        : DEFAULT_FORUM_CATEGORIES.map(item => ({ ...item })),
    };
  } catch {
    return { ...DEFAULT_CONFIG };
  }
}
export function saveForumGenerationConfig(config: ForumGenerationConfig): void {
  window.localStorage.setItem(CONFIG_KEY, JSON.stringify(config));
  window.dispatchEvent(new CustomEvent(FORUM_STATE_EVENT));
}
function customApi(config: ForumGenerationConfig): CustomApiConfig | undefined {
  if (config.apiSource !== 'custom') return undefined;
  let url: URL;
  try {
    url = new URL(config.apiUrl.trim());
  } catch {
    throw new Error('请输入有效的 API 地址');
  }
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password)
    throw new Error('API 地址必须是 HTTP 或 HTTPS 地址');
  if (!config.model.trim()) throw new Error('请填写模型名称');
  const apiConfig: CustomApiConfig = {
    apiurl: url.href.replace(/\/$/, ''),
    key: config.apiKey.trim() || undefined,
    model: config.model.trim(),
    source: 'openai',
    temperature: config.temperature,
    max_tokens: config.maxTokens,
  };
  return apiConfig;
}
export async function detectForumModels(config: ForumGenerationConfig, signal?: AbortSignal): Promise<string[]> {
  let url: URL;
  try {
    url = new URL(config.apiUrl.trim());
  } catch {
    throw new Error('请先填写有效的 API 地址');
  }
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password)
    throw new Error('API 地址必须是 HTTP 或 HTTPS 地址');
  url.search = '';
  url.hash = '';
  const base = url.pathname.replace(/\/+$/, '').replace(/\/(?:chat\/completions|models)$/, '');
  url.pathname = `${base || '/v1'}/models`;
  const controller = new AbortController();
  const abort = () => controller.abort();
  if (signal?.aborted) controller.abort();
  signal?.addEventListener('abort', abort, { once: true });
  const timer = window.setTimeout(abort, 15000);
  try {
    const response = await fetch(url.href, {
      method: 'GET',
      headers: config.apiKey.trim()
        ? { Authorization: `Bearer ${config.apiKey.trim()}`, Accept: 'application/json' }
        : { Accept: 'application/json' },
      signal: controller.signal,
      credentials: 'omit',
      redirect: 'error',
      cache: 'no-store',
    });
    if (!response.ok) {
      if (response.status === 401 || response.status === 403)
        throw new Error('模型列表鉴权失败，请检查 API Key 和访问权限');
      if (response.status === 404) throw new Error('未找到模型列表接口，请检查 API 基础地址；也可以手动填写模型');
      throw new Error(`模型检测失败（HTTP ${response.status}），请稍后重试`);
    }
    const payload: unknown = await response.json();
    const entries = Array.isArray(payload)
      ? payload
      : payload && typeof payload === 'object' && 'data' in payload
        ? payload.data
        : undefined;
    if (!Array.isArray(entries)) throw new Error('服务商返回的模型列表格式不受支持，可以手动填写模型');
    const models = [
      ...new Set(
        entries
          .map((entry: unknown) => {
            if (typeof entry === 'string') return entry.trim();
            if (entry && typeof entry === 'object' && 'id' in entry && typeof entry.id === 'string')
              return entry.id.trim();
            return '';
          })
          .filter(Boolean),
      ),
    ].sort((a, b) => a.localeCompare(b));
    if (!models.length) throw new Error('接口未返回可用模型，可以手动填写模型');
    return models;
  } catch (error) {
    if (controller.signal.aborted)
      throw new Error(signal?.aborted ? '已取消模型检测' : '模型检测超时，请检查地址或稍后重试');
    if (error instanceof TypeError)
      throw new Error('无法访问模型列表，请检查网络、地址和服务商的跨域设置；也可以手动填写模型');
    if (error instanceof SyntaxError) throw new Error('模型接口没有返回有效 JSON，请检查 API 基础地址');
    throw error;
  } finally {
    window.clearTimeout(timer);
    signal?.removeEventListener('abort', abort);
  }
}
export function forumErrorMessage(error: unknown): string {
  let text = error instanceof Error ? error.message : String(error || '论坛生成失败');
  const key = readForumGenerationConfig().apiKey;
  if (key) text = text.split(key).join('[已隐藏]');
  return text.slice(0, 300);
}
export async function testForumConnection(config: ForumGenerationConfig): Promise<void> {
  const api = customApi(config);
  const result = await generateRaw({
    should_stream: false,
    max_chat_history: 0,
    custom_api: api ? { ...api, max_tokens: 32 } : undefined,
    ordered_prompts: [{ role: 'user', content: '只回复：连接成功' }],
  });
  if (!result.trim()) throw new Error('连接成功但模型返回了空响应');
}
function getCleanChatHistory(): RolePrompt[] {
  return getChatMessages('0-{{lastMessageId}}', { hide_state: 'unhidden' })
    .map(item => ({
      role: item.role,
      content: String(item.message || '')
        .replace(/<(论坛|聊天)(?:\s[^>]*)?>[\s\S]*?<\/\1>/gi, '')
        .trim(),
    }))
    .filter(item => item.content && ['user', 'assistant', 'system'].includes(item.role))
    .slice(-24) as RolePrompt[];
}
async function loadForumPrompt(): Promise<{ content: string; source: string }> {
  const names = new Set<string>();
  try {
    const chat = getChatWorldbookName('current');
    if (chat) names.add(chat);
    const bound = getCharWorldbookNames('current');
    if (bound.primary) names.add(bound.primary);
    bound.additional.forEach(name => names.add(name));
    getGlobalWorldbookNames().forEach(name => names.add(name));
  } catch {
    /* Fall back to explicit entry names in available books. */
  }
  const boundNames = new Set(names);
  try {
    getWorldbookNames().forEach(name => names.add(name));
  } catch {
    /* Bound books may still be readable. */
  }
  let best: { content: string; source: string; rank: number } | undefined;
  for (const name of names) {
    try {
      const entries = await getWorldbook(name);
      for (const entry of entries) {
        const marker = entry.extra?.campusAppModule === 'forum' && entry.extra?.role === 'generation-prompt';
        const exact = /^(校园论坛生成规则|论坛提示词|校园论坛输出规则)$/.test(entry.name.trim());
        const legacy =
          boundNames.has(name) &&
          /论坛/.test(entry.name) &&
          /<论坛>/.test(entry.content) &&
          /<帖子/.test(entry.content) &&
          !/更新需求|收藏/.test(entry.name);
        const rank = marker ? 3 : exact ? 2 : legacy ? 1 : 0;
        if (rank && entry.content.trim() && (!best || rank > best.rank))
          best = { content: entry.content, source: `${name} / ${entry.name}`, rank };
      }
      if (best?.rank === 3) break;
    } catch {
      /* Continue to the next available worldbook. */
    }
  }
  if (best) return best;
  throw new Error('未找到论坛生成规则，请绑定含“论坛提示词”或“校园论坛生成规则”的世界书');
}
function repairMissingForumTextClosures(xml: string): string {
  const boundary = /<(?:标题|正文|内容|图片|回复|楼中楼|\/帖子|\/回复|\/楼中楼|\/论坛)(?:\s|>|\/)/g;
  for (const tag of ['标题', '正文', '内容']) {
    const token = new RegExp(`<\\/?${tag}>`, 'g');
    let open = false;
    const matches = [...xml.matchAll(boundary)].filter(
      match => match[0].startsWith(`<${tag}`) || /^<(?:图片|回复|楼中楼|\/)/.test(match[0]),
    );
    for (const match of matches.reverse()) {
      const position = match.index ?? 0;
      const previous = xml.slice(0, position);
      const tags = [...previous.matchAll(token)].map(item => item[0]);
      open = tags.filter(item => item === `<${tag}>`).length > tags.filter(item => item === `</${tag}>`).length;
      if (open && !match[0].startsWith(`<${tag}`)) xml = `${xml.slice(0, position)}</${tag}>${xml.slice(position)}`;
    }
  }
  return xml;
}

export function sanitizeGeneratedPosts(
  text: string,
  current: ForumPost[],
  postCount = readForumGenerationConfig().postCount,
  categories = readForumGenerationConfig().categories,
): IncomingForumPost[] {
  if (text.length > 100000) throw new Error('论坛响应过长，请减少输出 Tokens 后重试');
  let xml = text
    .trim()
    .replace(/^```(?:xml)?\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();
  if (/^<帖子(?:\s|>)/.test(xml)) xml = `<论坛>${xml}</论坛>`;
  xml = repairMissingForumTextClosures(xml);
  const doc = new DOMParser().parseFromString(xml, 'application/xml');
  if (doc.getElementsByTagName('parsererror').length || doc.documentElement.tagName !== '论坛' || doc.doctype)
    throw new Error('模型未返回有效的论坛 XML，请重试');
  if (
    [...doc.documentElement.children].some(node => node.tagName !== '帖子') ||
    [...doc.documentElement.childNodes].some(node => node.nodeType === 3 && node.textContent?.trim())
  )
    throw new Error('论坛容器中包含非帖子内容');
  const favoriteIds = new Set(readForumInteractions().favorited);
  const existing = new Map(current.map(post => [post.id, post]));
  const seen = new Set<string>();
  let newCount = 0;
  const output: IncomingForumPost[] = [];
  for (const node of [...doc.documentElement.children]) {
    const id = node.getAttribute('id')?.trim();
    if (!id || seen.has(id)) throw new Error('论坛帖子缺少 ID 或包含重复 ID');
    seen.add(id);
    const parsed = parseForumPostsFromText(`<论坛>${new XMLSerializer().serializeToString(node)}</论坛>`)[0];
    if (!parsed) throw new Error('帖子缺少有效标题或正文');
    if (parsed.delta && (!existing.has(id) || !favoriteIds.has(id))) throw new Error('模型尝试更新未收藏的旧帖');
    if (!parsed.delta && !categories.some(category => category.enabled && category.name === parsed.board))
      throw new Error(`生成结果使用了未启用的论坛分类：${parsed.board || '未命名'}`);
    if (!parsed.delta && ++newCount > postCount) throw new Error(`本次生成超过设置的 ${postCount} 个新帖`);
    if (
      !parsed.delta &&
      (!node.querySelector('标题')?.textContent?.trim() || !node.querySelector('正文')?.textContent?.trim())
    )
      throw new Error('新帖缺少标题或正文');
    if ((parsed.title?.length || 0) > 100 || (parsed.content?.length || 0) > 2000)
      throw new Error('论坛标题或正文超出长度限制');
    const oldReplyIds = new Set(existing.get(id)?.replies.map(reply => reply.id) || []);
    const replyIds = new Set<string>();
    const replies = parsed.replies.filter(reply => !oldReplyIds.has(reply.id));
    for (const reply of replies) {
      if (
        replyIds.has(reply.id) ||
        !reply.content.trim() ||
        reply.content.length > 1000 ||
        (reply.replies?.length || 0) > 2
      )
        throw new Error('论坛回复重复、为空或超出长度限制');
      replyIds.add(reply.id);
      if (
        reply.replies?.some(nested => nested.content.length > 1000 || !nested.content.trim() || nested.replies?.length)
      )
        throw new Error('楼中楼内容或层数无效');
    }
    if (parsed.media?.some(media => !media.description.trim() || media.description.length > 1000))
      throw new Error('图片描述为空或超出长度限制');
    if (
      parsed.replies.some(reply =>
        reply.media?.some(media => !media.description.trim() || media.description.length > 1000),
      )
    )
      throw new Error('回复图片描述为空或超出长度限制');
    if (replies.length > (parsed.delta ? 2 : 10)) throw new Error('单帖新增回复数量超出限制');
    // Deltas cannot overwrite the original post or existing replies.
    output.push(
      parsed.delta
        ? { id, delta: true, likes: parsed.likes, favorites: parsed.favorites, media: parsed.media, replies }
        : { ...parsed, replies },
    );
  }
  return output;
}
async function performGeneration(
  chatId: string,
  job: ActiveGeneration,
  config: ForumGenerationConfig,
  startedAt: number,
): Promise<ForumState> {
  const messages = readAssistantMessages();
  const target = messages[messages.length - 1];
  if (!target) throw new Error('当前聊天没有可用的 AI 回复');
  const previous = readForumState();
  const posts = previous.initialized || previous.posts.length ? previous.posts : loadForumPostsFromChat();
  const prompt = await loadForumPrompt();
  if (getForumChatId() !== chatId) throw new Error('聊天已切换，请在当前聊天重新生成');
  const history = getCleanChatHistory();
  if (job.reason) throw new Error('论坛生成已停止');
  const result = await generateRaw({
    should_stream: false,
    custom_api: customApi(config),
    generation_id: job.id,
    ordered_prompts: [
      { role: 'system', content: buildRequestPrompt(posts, prompt.content, config.postCount, config.categories) },
      ...history,
      { role: 'user', content: '根据以上公开剧情生成本轮论坛内容。' },
    ],
  });
  if (job.reason) throw new Error('论坛生成已停止');
  if (job.reason) throw new Error('论坛生成已停止');
  const latestMessages = readAssistantMessages();
  const latestMessage = latestMessages[latestMessages.length - 1];
  if (
    !job.reason &&
    getForumChatId() === chatId &&
    latestMessage?.message_id === target.message_id &&
    latestMessage?.message === target.message
  ) {
    const latest = readForumState();
    const current = latest.initialized || latest.posts.length ? latest.posts : posts;
    let incoming: IncomingForumPost[];
    try {
      incoming = sanitizeGeneratedPosts(result, current, config.postCount, config.categories);
    } catch (error) {
      throw new ForumGenerationError(forumErrorMessage(error), result);
    }
    const merged = mergeForumPosts(current, incoming);
    const changedIds = incoming.filter(post => !post.delta || post.replies.length > 0).map(post => post.id);
    const newReplies = incoming.reduce(
      (sum, post) => sum + post.replies.reduce((count, reply) => count + 1 + (reply.replies?.length || 0), 0),
      0,
    );
    const record: ForumGenerationRecord = {
      id: job.id,
      startedAt,
      durationMs: Date.now() - startedAt,
      status: 'success',
      model: config.apiSource === 'custom' ? config.model : '酒馆当前模型',
      newPosts: incoming.filter(post => !post.delta).length,
      newReplies,
      content: result.slice(0, 30000),
    };
    const next: ForumState = {
      ...latest,
      posts: merged,
      initialized: true,
      unreadPostIds: [...new Set([...(latest.unreadPostIds || []), ...changedIds])],
      records: [record, ...(latest.records || [])].slice(0, 20),
      lastGeneratedAt: Date.now(),
      lastError: undefined,
      promptSource: prompt.source,
    };
    saveForumState(next);
    return next;
  }
  throw new Error('生成结果已过期，已丢弃');
}
export function cancelForumGeneration(): void {
  const job = active.get(getForumChatId());
  if (!job) return;
  job.cancel('cancelled');
  const state = readForumState();
  const record: ForumGenerationRecord = {
    id: job.id,
    startedAt: Date.now(),
    durationMs: 0,
    status: 'cancelled',
    model: readForumGenerationConfig().model || '酒馆当前模型',
    newPosts: 0,
    newReplies: 0,
    error: '已取消论坛生成',
  };
  saveForumState({ ...state, records: [record, ...(state.records || [])].slice(0, 20), lastError: '已取消论坛生成' });
}
export function generateForumPosts(): Promise<ForumState> {
  const chatId = getForumChatId();
  const pending = active.get(chatId);
  if (pending) return pending.promise;
  const config = readForumGenerationConfig();
  const startedAt = Date.now();
  let rejectStop: (error: Error) => void = () => undefined;
  const stopped = new Promise<ForumState>((_resolve, reject) => {
    rejectStop = reject;
  });
  const job: ActiveGeneration = {
    id: `campus-forum-${crypto.randomUUID()}`,
    promise: stopped,
    cancel: reason => {
      if (job.reason) return;
      job.reason = reason;
      rejectStop(
        new Error(reason === 'timeout' ? `论坛生成超过 ${config.timeoutSeconds} 秒，已停止等待` : '已取消论坛生成'),
      );
      // Stop only this auxiliary request; never interrupt the main story generation.
      try {
        void stopGenerationById(job.id).catch(() => undefined);
      } catch {
        /* Late results are discarded even when stop is unsupported. */
      }
    },
  };
  active.set(chatId, job);
  const timer = window.setTimeout(() => job.cancel('timeout'), config.timeoutSeconds * 1000);
  job.promise = Promise.race([Promise.resolve().then(() => performGeneration(chatId, job, config, startedAt)), stopped])
    .catch(error => {
      if (getForumChatId() === chatId) {
        const state = readForumState();
        const generationError = error instanceof ForumGenerationError ? error : undefined;
        const record: ForumGenerationRecord = {
          id: job.id,
          startedAt,
          durationMs: Date.now() - startedAt,
          status: job.reason || 'error',
          model: config.apiSource === 'custom' ? config.model : '酒馆当前模型',
          newPosts: 0,
          newReplies: 0,
          error: forumErrorMessage(error),
          content:
            generationError?.rawContent ||
            `【错误信息】\n${forumErrorMessage(error)}\n\n【诊断说明】\n未收到模型原始响应。可能原因：\n- API 请求被拒绝（检查地址、模型、Key）\n- 网络超时或连接中断\n- 模型返回空内容\n\n排查建议：\n1. 点击"论坛设置 > 接口设置 > 测试连接"\n2. 按 F12 打开浏览器开发者工具，查看 Network 标签页\n3. 如使用"沿用酒馆"，确认酒馆主界面能正常对话`,
        };
        const failedState = {
          ...state,
          records: [record, ...(state.records || [])].slice(0, 20),
          lastError: record.error,
        };
        if (job.reason === 'cancelled' && state.processedMessageId >= 0) failedState.processedMessageId -= 1;
        saveForumState(failedState);
      }
      throw error;
    })
    .finally(() => {
      window.clearTimeout(timer);
      if (active.get(chatId) === job) active.delete(chatId);
      window.dispatchEvent(new CustomEvent(FORUM_STATE_EVENT));
    });
  window.dispatchEvent(new CustomEvent(FORUM_STATE_EVENT));
  return job.promise;
}
export function markForumRead(): void {
  const state = readForumState();
  if (state.unreadPostIds?.length) saveForumState({ ...state, unreadPostIds: [] });
}
export function clearForumData(): void {
  if (isForumGenerating()) cancelForumGeneration();
  const state = readForumState();
  saveForumState({
    ...state,
    posts: [],
    initialized: true,
    unreadPostIds: [],
    records: [],
    lastError: undefined,
    lastGeneratedAt: 0,
  });
  updateVariablesWith(
    variables => {
      _.set(variables, `${FORUM_STATE_PATH}.interactions`, { liked: [], favorited: [] });
      return variables;
    },
    { type: 'chat' },
  );
}
export function exportForumData(): string {
  return JSON.stringify({ version: 1, posts: readForumState().posts, interactions: readForumInteractions() }, null, 2);
}
export function downloadForumData(): void {
  const blob = new Blob([exportForumData()], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  try {
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `campus-forum-${new Date().toISOString().slice(0, 10)}.json`;
    anchor.click();
  } finally {
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
}
export function importForumData(text: string, replace = false): void {
  const value: unknown = JSON.parse(text);
  if (!value || typeof value !== 'object' || !Array.isArray((value as any).posts) || (value as any).posts.length > 500)
    throw new Error('论坛文件格式错误或帖子数量超限');
  const incoming = (value as any).posts;
  if (
    incoming.some(
      (post: any) =>
        !post ||
        typeof post.id !== 'string' ||
        typeof post.title !== 'string' ||
        typeof post.content !== 'string' ||
        !Array.isArray(post.replies),
    )
  )
    throw new Error('论坛文件包含无效帖子数据');
  const state = readForumState();
  const current = state.initialized || state.posts.length ? state.posts : loadForumPostsFromChat();
  const posts = replace ? incoming : mergeForumPosts(current, incoming);
  const interactions = (value as any).interactions;
  updateVariablesWith(
    variables => {
      _.set(variables, FORUM_STATE_PATH, {
        ...state,
        posts,
        initialized: true,
        unreadPostIds: [],
        records: state.records || [],
        schemaVersion: 2,
      });
      if (interactions && typeof interactions === 'object')
        _.set(variables, `${FORUM_STATE_PATH}.interactions`, {
          liked: Array.isArray(interactions.liked)
            ? interactions.liked.filter((id: unknown) => typeof id === 'string')
            : [],
          favorited: Array.isArray(interactions.favorited)
            ? interactions.favorited.filter((id: unknown) => typeof id === 'string').slice(0, 3)
            : [],
        });
      return variables;
    },
    { type: 'chat' },
  );
  window.dispatchEvent(new CustomEvent(FORUM_STATE_EVENT));
}
export function getLatestAssistantMessageId(): number {
  const messages = readAssistantMessages();
  return messages[messages.length - 1]?.message_id ?? -1;
}
export function markForumReplyProcessed(messageId: number): ForumState {
  const state = readForumState();
  if (messageId <= state.processedMessageId) return state;
  const next = { ...state, processedMessageId: messageId, replyCount: state.replyCount + 1 };
  saveForumState(next);
  return next;
}
export function markForumReplyForRetry(messageId: number): void {
  const state = readForumState();
  if (messageId === state.processedMessageId)
    saveForumState({ ...state, processedMessageId: messageId - 1, lastError: state.lastError });
}
export function notifyForumGeneration(): void {
  window.dispatchEvent(new CustomEvent(FORUM_GENERATE_EVENT));
}

function buildRequestPrompt(
  posts: ForumPost[],
  prompt: string,
  postCount: number,
  categories: ForumCategory[],
): string {
  const ids = new Set(readForumInteractions().favorited);
  const favorites = posts.filter(post => ids.has(post.id));
  const bounds = prompt.trim();
  return [
    bounds,
    '\n当前是前端独立的论坛辅助请求，只生成论坛，不生成剧情或聊天容器。',
    `本次目标生成 ${postCount} 个全新帖子，此数量覆盖上述规则中的默认数量。无公开新讨论可输出空容器，禁止凑数或超过 ${postCount} 个；收藏帖增量不计入新帖数量。只有以下收藏帖允许追加新回复，禁止改写原内容与旧回复：`,
    '图片规则：如果本轮公开剧情出现适合被拍摄、截图、传阅或展示的视觉信息，至少在一个相关帖子或回复中输出 1 条图片描述；否则不要强行添加图片。只输出文字描述，不要 URL、base64 或图片链接。格式必须是 `<图片 描述="..." />`，描述公开可见的主体、场景和动作，不超过 200 字。',
    allocateForumCategories(categories, postCount)
      .map(
        item =>
          `- ${item.name}: ${item.count} 个新帖，权重 ${item.weight}${item.description ? `，分类规则：${item.description}` : ''}`,
      )
      .join('\n'),
    JSON.stringify(
      favorites.map(post => ({ id: post.id, title: post.title, content: post.content, replies: post.replies })),
    ),
    '所有已有帖子 ID（禁止作为新帖复用）：' + posts.map(post => post.id).join(', '),
    '必须只输出唯一的 <论坛>...</论坛>；无新内容时输出 <论坛></论坛>。',
    '最终格式硬约束：第一字符必须是 <论坛>，最后字符必须是 </论坛>；每个 <帖子>、<标题>、<正文>、<内容> 都必须使用对应的</帖子>、</标题>、</正文>、</内容> 进行闭合；图片必须使用自闭合的 <图片 描述="..." />；禁止 Markdown、代码围栏、解释文字和半成品 XML。输出前先检查 XML 标签是否成对，无法保证完整时只输出 <论坛></论坛>。',
    'XML 转义要求：正文、标题和内容中的 & 必须写成 &amp;，< 必须写成 &lt;，> 必须写成 &gt;；属性值中的双引号必须写成 &quot;。',
  ].join('\n');
}
