import { useEffect, useMemo, useState } from 'react';
import { AlertCircle, Check, ChevronLeft, ChevronRight, FileText, Loader2, Search, X } from 'lucide-react';
import { CenterModal, FullScreenModal } from '../ui/Modal';
import { ConfirmDialog } from '../ui/ConfirmDialog';
import { showToast } from '../ui/Toast';
import type { WorldbookEntry } from '../../../../../../@types/function/worldbook';
import { getWorldbookManifest, WORLD_BOOK_NAMES } from '../../../../脚本/世界书/worldbookManifest';
import {
  applyWorldbookSelections,
  canApply,
  inspectWorldbook,
  migrateWorldbookBaseline,
  needsForce,
  readInstallRecords,
  type InstallRecords,
  type WorldbookDiff,
} from '../../../../脚本/世界书/worldbookSync';

const STATUS_LABELS: Record<WorldbookDiff['status'], string> = {
  new: '待新增',
  update: '官方有更新',
  custom: '检测到玩家修改',
  unknown: '尚无可信基线',
  current: '已是最新',
  runtime: '运行时数据，不参与更新',
  ambiguous: '存在同名条目，无法安全判断',
};

const STATUS_STYLES: Record<WorldbookDiff['status'], string> = {
  new: 'bg-sky-500/10 text-sky-600',
  update: 'bg-rose-500/10 text-rose-600',
  custom: 'bg-amber-500/10 text-amber-700',
  unknown: 'bg-amber-500/10 text-amber-700',
  current: 'bg-emerald-500/10 text-emerald-600',
  runtime: 'bg-slate-500/10 text-text-secondary',
  ambiguous: 'bg-red-500/10 text-red-600',
};


function selectableDiffs(diffs: WorldbookDiff[]): WorldbookDiff[] {
  return diffs.filter(diff => canApply(diff) && !needsForce(diff));
}
function displayContent(content: string): string {
  return content.replace(/\\n/g, '\n');
}


export function WorldbookUpdateModal({ onClose }: { onClose: () => void }) {
  const manifest = useMemo(() => getWorldbookManifest(), []);
  const [worldbooks, setWorldbooks] = useState<string[]>([]);
  const [selectedBook, setSelectedBook] = useState('');
  const [entries, setEntries] = useState<WorldbookEntry[]>([]);
  const [records, setRecords] = useState<InstallRecords>({});
  const [showSkippedNotice, setShowSkippedNotice] = useState(false);
  const [boundBooks, setBoundBooks] = useState<string[]>([]);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [forcedIds, setForcedIds] = useState<string[]>([]);
  const [details, setDetails] = useState<WorldbookDiff | null>(null);
  const [confirmForce, setConfirmForce] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    try {
      const books = getWorldbookNames().filter(name => WORLD_BOOK_NAMES.includes(name));
      setWorldbooks(books);
      if (books.length) setSelectedBook(books[0]);
      const binding = getCharWorldbookNames('current');
      setBoundBooks([binding.primary, ...binding.additional].filter((name): name is string => Boolean(name)));
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : String(reason));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!selectedBook) return;
    let alive = true;
    setLoading(true);
    setError('');
    setShowSkippedNotice(false);
    setSelectedIds([]);
    setForcedIds([]);
    void getWorldbook(selectedBook)
      .then(bookEntries => {
        if (!alive) return;
        const savedRecords = migrateWorldbookBaseline(selectedBook, bookEntries, manifest);
        setEntries(bookEntries);
        setRecords(savedRecords);

      })
      .catch(reason => {
        if (alive) setError(reason instanceof Error ? reason.message : String(reason));
      })
      .finally(() => alive && setLoading(false));
    return () => { alive = false; };
  }, [manifest, selectedBook]);

  const diffs = useMemo(
    () => selectedBook ? inspectWorldbook(selectedBook, entries, manifest, records) : [],
    [entries, manifest, records, selectedBook],
  );
  const actionable = diffs.filter(canApply);
  const skippedDiffs = actionable.filter(needsForce);
  const allNormalSelected = selectableDiffs(diffs).length > 0
    && selectableDiffs(diffs).every(diff => selectedIds.includes(diff.manifest.id));
  const chosen = diffs.filter(diff => selectedIds.includes(diff.manifest.id) || forcedIds.includes(diff.manifest.id));
  const forced = chosen.filter(diff => forcedIds.includes(diff.manifest.id));

  const toggleSelected = (id: string) => setSelectedIds(current => current.includes(id)
    ? current.filter(item => item !== id)
    : [...current, id]);
  const toggleForced = (id: string) => setForcedIds(current => current.includes(id)
    ? current.filter(item => item !== id)
    : [...current, id]);

  const applyChosen = async () => {
    setSaving(true);
    try {
      const nextEntries = await applyWorldbookSelections(selectedBook, chosen, manifest, forced.length > 0);
      setEntries(nextEntries);
      setRecords(readInstallRecords());
      setSelectedIds([]);
      setForcedIds([]);
      showToast(`已应用 ${chosen.length} 项更新`, 'success');
      setConfirmForce(false);
    } catch (reason) {
      const message = reason instanceof Error ? reason.message : '世界书更新失败';
      setError(message);
      showToast(message, 'error');
    } finally {
      setSaving(false);
    }
  };

  const requestApply = () => {
    if (!chosen.length || saving) return;
    if (forced.length) {
      setConfirmForce(true);
      return;
    }
    void applyChosen();
  };

  const toggleAllNormal = () => {
    if (!allNormalSelected && skippedDiffs.length) setShowSkippedNotice(true);
    const ids = selectableDiffs(diffs).map(diff => diff.manifest.id);
    setSelectedIds(current => allNormalSelected
      ? current.filter(id => !ids.includes(id))
      : [...new Set([...current, ...ids])]);
  };

  return (
    <FullScreenModal isOpen className="z-[95]">
      <div className="px-5 py-4 shrink-0 border-b border-border-default/30 flex items-center gap-3">
        <button type="button" onClick={onClose} className="p-2 -ml-2 rounded-full hover:bg-surface text-text-secondary" aria-label="返回"><ChevronLeft className="w-5 h-5" /></button>
        <div className="min-w-0 flex-1"><h2 className="text-lg font-bold text-text-primary">世界书更新</h2><p className="text-[11px] text-text-secondary">逐条检查并选择应用；更新不会改变世界书绑定</p></div>
      </div>
      <div className="flex-1 min-h-0 overflow-y-auto p-4 space-y-3">
        {worldbooks.length > 1 && <div className="space-y-2"><div className="text-xs font-semibold text-text-secondary">选择目标世界书</div>{worldbooks.map(book => {
          const selected = selectedBook === book;
          return <button type="button" key={book} onClick={() => setSelectedBook(book)} className={`w-full flex items-center gap-3 rounded-xl border p-3 text-left ${selected ? 'border-rose-300 bg-rose-500/5' : 'border-border-default bg-surface-solid hover:bg-surface'}`}><span className={`flex h-4 w-4 items-center justify-center rounded-full border-2 ${selected ? 'border-rose-500' : 'border-border-default'}`}>{selected && <span className="h-2 w-2 rounded-full bg-rose-500" />}</span><span className="min-w-0 flex-1 truncate text-sm font-semibold text-text-primary">{book}</span>{boundBooks.includes(book) && <span className="rounded-full bg-emerald-500/10 px-2 py-1 text-[10px] font-medium text-emerald-600">当前绑定</span>}<ChevronRight className="h-4 w-4 text-text-secondary" /></button>;
        })}</div>}
        {worldbooks.length === 1 && <div className="flex items-center justify-between rounded-xl border border-border-default bg-surface-solid p-3 text-sm font-bold text-text-primary">{selectedBook}{boundBooks.includes(selectedBook) && <span className="rounded-full bg-emerald-500/10 px-2 py-1 text-[10px] font-medium text-emerald-600">当前绑定</span>}</div>}
        {loading && <div className="py-10 flex justify-center"><Loader2 className="w-5 h-5 animate-spin text-text-secondary" /></div>}
        {!loading && worldbooks.length === 0 && <div className="rounded-xl border border-border-default p-4 text-sm text-text-secondary">没有找到已登记的校园世界书。当前只识别：{WORLD_BOOK_NAMES.join('、')}</div>}
        {!loading && selectedBook && <>
          <div className="flex items-center gap-2 px-1 py-2"><span className="text-xs text-text-secondary">{actionable.length} 项可处理</span><button type="button" disabled={!actionable.length} onClick={toggleAllNormal} className="ml-auto rounded-lg border border-border-default px-2.5 py-1.5 text-[11px] font-semibold text-text-secondary disabled:opacity-40">{allNormalSelected ? '取消全选' : '全选'}</button></div>
          {diffs.map(diff => {
            const id = diff.manifest.id;
            const forceRequired = needsForce(diff);
            const selected = selectedIds.includes(id);
            const forceSelected = forcedIds.includes(id);
            return <div key={id} className="rounded-xl border border-border-default bg-surface-solid p-3">
              <div className="flex items-start gap-3">
                <input type="checkbox" aria-label={`选择${diff.manifest.name}`} disabled={!canApply(diff) || forceRequired} checked={selected} onChange={() => toggleSelected(id)} className="mt-1 h-4 w-4 accent-rose-500 disabled:opacity-30" />
                <div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="text-sm font-semibold text-text-primary">{diff.manifest.name}</span><span className={`rounded px-1.5 py-0.5 text-[9px] font-bold ${STATUS_STYLES[diff.status]}`}>{STATUS_LABELS[diff.status]}</span></div><p className="mt-1 text-[10px] text-text-secondary">版本 {diff.manifest.version}</p>{forceRequired && <label className="mt-2 flex cursor-pointer items-start gap-2 text-[11px] leading-relaxed text-amber-700"><input type="checkbox" checked={forceSelected} onChange={() => toggleForced(id)} className="mt-0.5 h-4 w-4 accent-amber-600" /><span>强制覆盖此条目。内容和其他配置将替换为官方版本；现有启用状态会保留（校园论坛输出规则除外，始终关闭）。</span></label>}</div>
                <button type="button" onClick={() => setDetails(diff)} className="rounded-lg p-2 text-text-secondary hover:bg-surface" aria-label="查看条目差异"><Search className="h-4 w-4" /></button>
              </div>
            </div>;
          })}
          {actionable.length === 0 && <div className="py-8 text-center text-sm text-emerald-600">没有待处理的官方更新</div>}
        </>}
        {error && <div className="flex gap-2 text-xs text-rose-500"><AlertCircle className="h-4 w-4 shrink-0" />{error}</div>}
      </div>
      {selectedBook && <div className="shrink-0 border-t border-border-default/30 p-4"><button type="button" disabled={!chosen.length || saving} onClick={requestApply} className="flex w-full items-center justify-center gap-2 rounded-xl bg-rose-500 py-3 text-sm font-bold text-white disabled:opacity-50"><Check className="h-4 w-4" />{saving ? '正在更新…' : `应用所选 (${chosen.length})`}</button></div>}
      <CenterModal isOpen={Boolean(details)} onClose={() => setDetails(null)} className="w-full max-w-lg max-h-[85%]">
        {details && <><div className="flex items-center gap-3 border-b border-border-default p-4"><FileText className="h-4 w-4 shrink-0 text-text-secondary" /><div className="min-w-0 flex-1 truncate text-sm font-bold text-text-primary">{details.manifest.name}</div><span className="shrink-0 rounded-full bg-rose-500/10 px-2.5 py-1 text-[10px] font-semibold text-rose-600">v{details.manifest.version}</span><button type="button" onClick={() => setDetails(null)} className="shrink-0 rounded-lg p-1.5 text-text-secondary hover:bg-surface" aria-label="关闭"><X className="h-4 w-4" /></button></div><div className="flex-1 min-h-0 space-y-4 overflow-y-auto p-4">{([['酒馆当前配置', details.local], ['官方目标配置', details.manifest.entry]] as const).map(([title, entry]) => <section key={title} className="min-w-0 space-y-3"><div className="flex items-center gap-2"><span className="h-1.5 w-1.5 rounded-full bg-rose-400" /><h3 className="text-sm font-bold text-text-primary">{title}</h3></div><div className="flex flex-wrap gap-1.5"><span className={`rounded-full px-2.5 py-1 text-[10px] font-semibold ${entry?.enabled ? 'bg-emerald-500/10 text-emerald-700' : 'bg-slate-500/10 text-text-secondary'}`}>{entry?.enabled ? '已启用' : '未启用'}</span><span className={`rounded-full px-2.5 py-1 text-[10px] font-semibold ${entry?.strategy.type === 'constant' ? 'bg-sky-500/10 text-sky-700' : entry?.strategy.type === 'selective' ? 'bg-green-500/10 text-green-700' : 'bg-slate-500/10 text-text-secondary'}`}>{entry?.strategy.type === 'constant' ? '蓝灯 · 常量激活' : entry?.strategy.type === 'selective' ? '绿灯 · 关键字激活' : entry ? '其他激活方式' : '条目不存在'}</span></div><div className="space-y-1.5"><div className="text-[10px] font-semibold text-text-secondary">关键字</div><div className="flex flex-wrap gap-1.5">{entry?.strategy.keys.length ? entry.strategy.keys.map((key, index) => <span key={`${String(key)}-${index}`} className="max-w-full break-all rounded-md border border-border-default bg-surface px-2 py-1 text-[10px] text-text-secondary">{key instanceof RegExp ? `/${key.source}/${key.flags}` : key}</span>) : <span className="rounded-md bg-surface px-2 py-1 text-[10px] text-text-secondary">无</span>}</div></div><pre className="campus-scrollbar max-h-56 overflow-auto whitespace-pre-wrap break-words rounded-lg border border-border-default/60 bg-surface p-3 text-[11px] leading-relaxed text-text-primary">{entry ? displayContent(entry.content) : '条目不存在'}</pre></section>)}</div></>}
      </CenterModal>
      <ConfirmDialog open={showSkippedNotice} title="部分条目需手动勾选" message={`以下 ${skippedDiffs.length} 项检测到玩家修改或缺少可信基线，未纳入全选：\n${skippedDiffs.map(diff => `• ${diff.manifest.name}`).join('\n')}\n\n如需更新，请自行检查，并手动勾选对应条目的“强制覆盖此条目”。`} confirmText="知道了" hideCancel onClose={() => setShowSkippedNotice(false)} onConfirm={() => setShowSkippedNotice(false)} />
      <ConfirmDialog open={confirmForce} title="确认强制覆盖" message={`以下 ${forced.length} 个条目已检测到玩家修改或缺少可信基线：\n${forced.map(diff => `• ${diff.manifest.name}`).join('\n')}\n\n继续后，这些条目的内容与完整配置将被官方版本替换。此操作无法自动恢复。`} confirmText="确认覆盖" cancelText="返回检查" onClose={() => setConfirmForce(false)} onConfirm={() => void applyChosen()} />
    </FullScreenModal>
  );
}
