import { useEffect, useMemo, useRef } from 'react';
import { syncFavoritedPostsToWorldbook } from '../utils/forumFavoriteWorldbook';
import { useForumInteractions } from './useForumInteractions';
import { useForumPosts } from './useForumPosts';

export function useForumFavoriteWorldbookSync() {
  const posts = useForumPosts();
  const { favoritedIds } = useForumInteractions();
  const timerRef = useRef<number | null>(null);

  const favoritePosts = useMemo(
    () => favoritedIds.map(id => posts.find(post => post.id === id)).filter((post): post is NonNullable<typeof post> => Boolean(post)),
    [favoritedIds, posts],
  );

  useEffect(() => {
    if (timerRef.current) window.clearTimeout(timerRef.current);
    timerRef.current = window.setTimeout(() => {
      void syncFavoritedPostsToWorldbook(favoritePosts);
    }, 250);

    return () => {
      if (timerRef.current) window.clearTimeout(timerRef.current);
    };
  }, [favoritePosts]);
}
