import React, { useState, useEffect, useRef, useCallback } from 'react';
import { CampusBuilding, Character, SchoolRule } from '../../types';
import { FullScreenModal, BottomSheetModal } from '../ui/Modal';
import { Map, ChevronLeft, Hammer, Pencil, Trash2, Move } from 'lucide-react';
import { useDraggableScroll } from '../../hooks/useDraggableScroll';
import { BuildingDetailsModal } from './BuildingDetailsModal';
import { getBuildingVisualStyle, BUILDING_COLORS, BUILDING_COLOR_PALETTES } from '../../data';
import { isTimestampInRange } from '../../utils/forumParser';
import { showToast, clearInfoToasts } from '../ui/Toast';
import { useCampusTheme } from '../../hooks/useCampusTheme';
import { SizeStepper } from '../shared/SizeStepper';
import { fillTavernInput } from '../../utils/fillTavernInput';

const MAP_STARS = Array.from({ length: 72 }, (_, i) => ({
  left: `${((i * 53) % 96) + 2}%`,
  top: `${((i * 37) % 93) + 3}%`,
  size: i % 9 === 0 ? 3.5 : i % 4 === 0 ? 2.2 : 1.3,
  delay: `${((i * 13) % 28) / 10}s`,
  duration: `${1.8 + (i % 6) * 0.35}s`,
  glow: i % 5 === 0,
}));

interface MapScreenProps {
  buildings: CampusBuilding[];
  onBuildingsChange: (buildings: CampusBuilding[]) => void;
  characters: Character[];
  rules: SchoolRule[];
  nowTs: number;
  onClose: () => void;
  onCharacterClick: (char: Character) => void;
}

type PlacingMode = 'create' | 'move';

interface PlacingState {
  mode: PlacingMode;
  building: {
    id?: string;
    name: string;
    width: number;
    height: number;
    color: string;
    description?: string;
  };
  previewX: number | null;
  previewY: number | null;
  originalBuilding?: CampusBuilding;
}

export const MapScreen: React.FC<MapScreenProps> = ({ 
  buildings, 
  onBuildingsChange,
  characters,
  rules,
  nowTs,
  onClose,
  onCharacterClick 
}) => {
  const { isDark } = useCampusTheme();
  const dragProps = useDraggableScroll<HTMLDivElement>();
  const buildScrollProps = useDraggableScroll<HTMLDivElement>();
  const editScrollProps = useDraggableScroll<HTMLDivElement>();
  const mapPalette = isDark
    ? {
        ground: 'linear-gradient(180deg, #0f1724 0%, #152018 42%, #101820 100%)',
        road: '#2b3240',
        roadBorder: '#8d7a62',
        wall: 'rgba(15, 23, 36, 0.78)',
        wallLine: 'rgba(148, 163, 184, 0.28)',
        wallDot: 'rgba(251, 191, 36, 0.32)',
        gateLine: '#fbbf24',
      }
    : {
        ground: '#E8F5E9',
        road: '#FDFBF7',
        roadBorder: '#A38980',
        wall: 'rgba(255, 255, 255, 0.5)',
        wallLine: 'rgba(203, 213, 225, 0.7)',
        wallDot: 'rgba(5, 150, 105, 0.2)',
        gateLine: '#d4af37',
      };
  
  // 32x31 格子体系 (左右围墙各2格，校内东西各12格可用，中央大道4格；上下围墙各2格，四排建筑区各6格高，三条横向路各1格)
  const GRID_WIDTH = 32;
  const GRID_HEIGHT = 31;
  const CELL_SIZE = 60; 
  const GAP = 6; 
  const PADDING = 16; 
  const MAP_WIDTH = GRID_WIDTH * CELL_SIZE + (GRID_WIDTH - 1) * GAP + PADDING * 2;
  const MAP_HEIGHT = GRID_HEIGHT * CELL_SIZE + (GRID_HEIGHT - 1) * GAP + PADDING * 2;

  // 始终保持固定缩放倍率为 35%
  const zoom = 0.35;

  const centerMap = useCallback(() => {
    if (dragProps.ref.current) {
      const container = dragProps.ref.current;
      requestAnimationFrame(() => {
        const offsetShiftY = 2 * (CELL_SIZE + GAP) * zoom;
        container.scrollTop = Math.max(0, (container.scrollHeight - container.clientHeight) / 2 + offsetShiftY);
        container.scrollLeft = Math.max(0, (container.scrollWidth - container.clientWidth) / 2);
      });
    }
  }, [dragProps.ref, zoom, CELL_SIZE, GAP]);

  useEffect(() => {
    const timer = setTimeout(() => {
      centerMap();
    }, 80);
    return () => clearTimeout(timer);
  }, [centerMap]);

  const [showBuildModal, setShowBuildModal] = useState(false);
  const [buildForm, setBuildForm] = useState({ name: '', width: 5, height: 3, color: BUILDING_COLORS[0], description: '' });
  
  const [placingState, setPlacingState] = useState<PlacingState | null>(null);
  
  const [selectedBuilding, setSelectedBuilding] = useState<CampusBuilding | null>(null);
  const [isEditMode, setIsEditMode] = useState(false);
  const [editingBuilding, setEditingBuilding] = useState<CampusBuilding | null>(null);

  const handleToggleEditMode = () => {
    const next = !isEditMode;
    setIsEditMode(next);
    if (next) {
      showToast('请点击想要编辑的建筑', 'info', 0);
    } else {
      clearInfoToasts();
    }
  };

  const timerRef = useRef<NodeJS.Timeout | null>(null);
  const wasLongPressed = useRef(false);
  const pointerDownPos = useRef<{x: number, y: number} | null>(null);

  const handlePointerDown = (e: React.PointerEvent, b: CampusBuilding) => {
    if (placingState || b.id === 'gate') return;
    e.currentTarget.setPointerCapture(e.pointerId);
    wasLongPressed.current = false;
    pointerDownPos.current = { x: e.clientX, y: e.clientY };
    timerRef.current = setTimeout(() => {
      timerRef.current = null;
      wasLongPressed.current = true;
      pointerDownPos.current = null;
      setPlacingState({
        mode: 'move',
        building: { ...b },
        previewX: b.x,
        previewY: b.y,
        originalBuilding: b
      });
      showToast(`请点击地图选择 ${b.name} 的新位置`, 'info', 0);
      setEditingBuilding(null);
      setSelectedBuilding(null);
    }, 180);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (pointerDownPos.current && timerRef.current) {
      const dx = Math.abs(e.clientX - pointerDownPos.current.x);
      const dy = Math.abs(e.clientY - pointerDownPos.current.y);
      if (dx > 5 || dy > 5) {
        clearTimeout(timerRef.current);
        timerRef.current = null;
      }
    }
  };

  const handlePointerUp = () => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
    pointerDownPos.current = null;
  };

  const handleStartBuild = () => {
    if (!buildForm.name.trim()) return;
    setPlacingState({
      mode: 'create',
      building: { ...buildForm },
      previewX: null,
      previewY: null
    });
    setShowBuildModal(false);
    showToast(`请点击地图选择 ${buildForm.name} 的位置 (${buildForm.width}x${buildForm.height})`, 'info', 0);
    setBuildForm({ name: '', width: 5, height: 3, color: BUILDING_COLORS[0], description: '' }); 
  };
  
  const handleStartMove = () => {
    if (!editingBuilding) return;
    setPlacingState({
      mode: 'move',
      building: { ...editingBuilding },
      previewX: editingBuilding.x,
      previewY: editingBuilding.y,
      originalBuilding: editingBuilding
    });
    showToast(`请点击地图选择 ${editingBuilding.name} 的新位置`, 'info', 0);
    setEditingBuilding(null);
  };

  // 处理方格点击与放置判断
  const handleCellClick = (x: number, y: number) => {
    if (!placingState) return;
    
    // 检查是否碰撞围墙（围墙宽度2格：四周边界 0..1 和 GRID_WIDTH-2..GRID_WIDTH-1 / GRID_HEIGHT-2..GRID_HEIGHT-1）
    let hitsWall = false;
    for (let i = x; i < x + placingState.building.width; i++) {
      for (let j = y; j < y + placingState.building.height; j++) {
        if (i <= 1 || i >= GRID_WIDTH - 2 || j <= 1 || j >= GRID_HEIGHT - 2) {
          hitsWall = true;
        }
      }
    }
    
    if (hitsWall) {
      showToast('无法在2格围墙上或校园外建造！', 'error');
      return;
    }

    // 检查与其他建筑重叠
    const isOverlap = buildings.some(b => 
      b.id !== placingState.building.id && 
      x < b.x + b.width && 
      x + placingState.building.width > b.x && 
      y < b.y + b.height && 
      y + placingState.building.height > b.y
    );

    if (isOverlap) {
      showToast('该位置已有建筑，无法放置！', 'error');
      return;
    }

    setPlacingState(prev => prev ? { ...prev, previewX: x, previewY: y } : null);
  };
  
  const handleConfirmPlace = () => {
    if (!placingState || placingState.previewX === null || placingState.previewY === null) return;
    if (placingState.mode === 'create') {
      const command = `在校园新增建筑「${placingState.building.name}」，坐标为 X=${placingState.previewX}、Y=${placingState.previewY}，宽度 ${placingState.building.width} 格、高度 ${placingState.building.height} 格，建筑描述为「${placingState.building.description?.trim() || '无'}」。建筑类型设为「学习设施」。请通过 MVU 变量更新写入「校园建筑」，保留其他建筑数据。`;
      if (!fillTavernInput(command)) {
        showToast('未能写入酒馆输入栏，建筑未保存，请重试', 'error');
        return;
      }
      showToast('新增建筑指令已写入酒馆输入栏，发送后等待 AI 更新', 'success');
      clearInfoToasts();
      setPlacingState(null);
      return;
    }

    const nextBuildings = buildings.map(b => {
          if (b.id === placingState.originalBuilding?.id) {
            return {
              ...placingState.originalBuilding!,
              ...placingState.building,
              x: placingState.previewX!,
              y: placingState.previewY!,
            };
          }
          return b;
        });

    onBuildingsChange(nextBuildings);
    clearInfoToasts();
    setPlacingState(null);
  };

  const handleCancelPlace = () => {
    clearInfoToasts();
    setPlacingState(null);
  };

  const handleClose = () => {
    clearInfoToasts();
    onClose();
  };

  const displayBuildings = buildings.filter(b => 
    !(placingState?.mode === 'move' && b.id === placingState.originalBuilding?.id) && b.type !== 'road'
  );

  return (
    <FullScreenModal isOpen={true} className="z-20 bg-surface-solid flex flex-col p-0 select-none">
      <style>{`
        @keyframes floating {
          0% { transform: translateY(0px); }
          50% { transform: translateY(-6px); }
          100% { transform: translateY(0px); }
        }
        .animate-floating {
          animation: floating 2s ease-in-out infinite;
        }

        /* 飘动的浮云动画 */
        @keyframes cloud-drift-fast {
          0% { transform: translate3d(-360px, 0, 0); }
          100% { transform: translate3d(1800px, 0, 0); }
        }
        @keyframes cloud-drift-mid {
          0% { transform: translate3d(-420px, 0, 0); }
          100% { transform: translate3d(1800px, 0, 0); }
        }
        @keyframes cloud-drift-slow {
          0% { transform: translate3d(-500px, 0, 0); }
          100% { transform: translate3d(1800px, 0, 0); }
        }
        @keyframes cloud-gentle-bob {
          0%, 100% { transform: translateY(0px); }
          50% { transform: translateY(-10px); }
        }
        @keyframes star-twinkle {
          0%, 100% { opacity: 0.22; transform: scale(0.75); }
          50% { opacity: 1; transform: scale(1.2); }
        }
      `}</style>
      
      {/* ================= 顶部导航层 ================= */}
      <div className="relative shrink-0 z-50 border-b border-border-default/30 flex justify-between items-center p-4 bg-surface-solid">
        <h1 className="text-xl font-bold text-text-primary flex items-center gap-2">
          <Map className="w-6 h-6 text-[color:var(--action-text)]" />
          校园地图
        </h1>
        <div className="flex items-center gap-2">
          <button 
            onClick={handleToggleEditMode} 
            className={`p-2 glass rounded-full hover-fill text-text-primary hover:text-[color:var(--action-text)] transition-colors shadow-sm cursor-pointer ${isEditMode ? 'text-[color:var(--action-text)] ring-2 ring-[color:var(--selected-border)]' : ''}`}
            title={isEditMode ? "退出编辑" : "编辑建筑"}
          >
            <Pencil className="w-5 h-5" />
          </button>
          <button 
            onClick={() => setShowBuildModal(true)} 
            className="p-2 glass rounded-full hover-fill text-text-primary hover:text-[color:var(--action-text)] transition-colors shadow-sm cursor-pointer"
            title="规划建筑"
          >
            <Hammer className="w-5 h-5" />
          </button>
          <button 
            onClick={handleClose} 
            className="p-2 glass rounded-full hover-fill text-text-primary hover:text-[color:var(--action-text)] transition-colors shadow-sm cursor-pointer"
            title="返回"
          >
            <ChevronLeft className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* ================= 放置确认栏 ================= */}
      {placingState && (
        <div className="absolute bottom-4 left-0 w-full px-8 z-50 flex justify-between pointer-events-none">
          <button 
            onClick={handleCancelPlace}
            className="pointer-events-auto w-32 py-3.5 bg-surface-solid text-text-primary rounded-full font-bold shadow-[0_8px_30px_rgb(0,0,0,0.12)] border-2 border-border-default hover-fill transition-all active:scale-95 cursor-pointer"
          >
            取消
          </button>
          <button 
            onClick={handleConfirmPlace}
            disabled={placingState.previewX === null}
            className="pointer-events-auto w-32 py-3.5 accent-btn rounded-full font-bold shadow-sm transition-all active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer"
          >
            确认放置
          </button>
        </div>
      )}

      {/* ================= 地图拖动与缩放视口层 ================= */}
      <div 
        className="relative flex-1 min-h-0 w-full overflow-auto hide-scrollbar cursor-grab active:cursor-grabbing touch-none pb-6 z-0"
        {...dragProps} ref={dragProps.ref}
      >
        <div 
          className="w-max h-max min-w-full min-h-full flex items-center justify-center"
          style={{
            padding: Math.max(48, Math.round(72 * zoom))
          }}
        >
          {/* 缩放定位容器 */}
          <div 
            className="relative transition-[width,height] duration-200"
            style={{ 
              width: MAP_WIDTH * zoom, 
              height: MAP_HEIGHT * zoom,
              minWidth: MAP_WIDTH * zoom,
              minHeight: MAP_HEIGHT * zoom,
            }}
          >
            {/* 校园地图主画布（非道路区域地面底色为 #E8F5E9，无方格轮廓） */}
            <div 
              className="relative rounded-3xl shadow-[0_20px_50px_rgba(0,0,0,0.12)] box-content origin-top-left overflow-hidden"
              style={{ 
                width: MAP_WIDTH, 
                height: MAP_HEIGHT,
                transform: `scale(${zoom})`,
                transformOrigin: '0 0',
                background: mapPalette.ground,
              }}
            >
              {/* ================= 校园道路层 (中间竖着一条正中主干大道 x=15..16 宽2格，横着三条路 y=8, y=15, y=22，道路间距均为精准6格，底色 #FDFBF7，带有 #A38980 虚线边框) ================= */}
              {/* 纵向中央主干道 (x: 15..16，宽 2 格，南北正中贯通连接大门) */}
              <div 
                className="absolute shadow-inner pointer-events-none z-1 border-x-[4px] border-dashed"
                style={{
                  left: PADDING + 15 * (CELL_SIZE + GAP),
                  top: PADDING + 2 * (CELL_SIZE + GAP),
                  width: 2 * CELL_SIZE + GAP,
                  height: (GRID_HEIGHT - 4) * (CELL_SIZE + GAP) - GAP,
                  background: mapPalette.road,
                  borderColor: mapPalette.roadBorder,
                }}
              />

              {/* 横向路 1 (y: 8, 位于第1排与第2排建筑之间，贯通东西，上下建筑区均为6格高度) */}
              <div 
                className="absolute shadow-inner pointer-events-none z-1 border-y-[4px] border-dashed"
                style={{
                  left: PADDING + 2 * (CELL_SIZE + GAP),
                  top: PADDING + 8 * (CELL_SIZE + GAP),
                  width: (GRID_WIDTH - 4) * (CELL_SIZE + GAP) - GAP,
                  height: CELL_SIZE,
                  background: mapPalette.road,
                  borderColor: mapPalette.roadBorder,
                }}
              />

              {/* 横向路 2 (y: 15, 位于第2排与第3排建筑之间，贯通东西，上下道路间距均为6格) */}
              <div 
                className="absolute shadow-inner pointer-events-none z-1 border-y-[4px] border-dashed"
                style={{
                  left: PADDING + 2 * (CELL_SIZE + GAP),
                  top: PADDING + 15 * (CELL_SIZE + GAP),
                  width: (GRID_WIDTH - 4) * (CELL_SIZE + GAP) - GAP,
                  height: CELL_SIZE,
                  background: mapPalette.road,
                  borderColor: mapPalette.roadBorder,
                }}
              />

              {/* 横向路 3 (y: 22, 位于第3排与第4排建筑之间，贯通东西，上下道路间距均为6格) */}
              <div 
                className="absolute shadow-inner pointer-events-none z-1 border-y-[4px] border-dashed"
                style={{
                  left: PADDING + 2 * (CELL_SIZE + GAP),
                  top: PADDING + 22 * (CELL_SIZE + GAP),
                  width: (GRID_WIDTH - 4) * (CELL_SIZE + GAP) - GAP,
                  height: CELL_SIZE,
                  background: mapPalette.road,
                  borderColor: mapPalette.roadBorder,
                }}
              />

              {/* ================= 连续一体围墙 (Wall Outer Shell - 2格厚度，半透明浅色系) ================= */}
              {/* 顶部整条连续围墙 (厚度 2 格: y: 0..1, 从 x=0 到 x=31) */}
              <div 
                className="absolute backdrop-blur-xs border shadow-xs pointer-events-none z-10 rounded-t-2xl flex flex-col items-center justify-center overflow-hidden"
                style={{
                  left: PADDING,
                  top: PADDING,
                  width: GRID_WIDTH * CELL_SIZE + (GRID_WIDTH - 1) * GAP,
                  height: 2 * CELL_SIZE + GAP,
                  background: mapPalette.wall,
                  borderColor: mapPalette.wallLine,
                }}
              >
                <div className="w-full h-1.5 absolute top-2" style={{ background: mapPalette.wallLine }} />
                <div className="w-full h-0.5 absolute top-4" style={{ background: isDark ? 'rgba(251,191,36,0.18)' : 'rgba(255,255,255,0.7)' }} />
                {/* 顶部围墙垛口微装饰 */}
                <div className="w-full flex justify-between px-6">
                  {Array.from({ length: 16 }).map((_, i) => (
                    <div key={i} className="w-2.5 h-2.5 rounded-full" style={{ background: mapPalette.wallDot }} />
                  ))}
                </div>
              </div>

              {/* 左侧整条连续围墙 (厚度 2 格: x: 0..1) */}
              <div 
                className="absolute backdrop-blur-xs border-l border-r shadow-xs pointer-events-none z-10 flex flex-col justify-between py-4 items-center overflow-hidden"
                style={{
                  left: PADDING,
                  top: PADDING + 2 * (CELL_SIZE + GAP),
                  width: 2 * CELL_SIZE + GAP,
                  height: (GRID_HEIGHT - 4) * (CELL_SIZE + GAP) - GAP,
                  background: mapPalette.wall,
                  borderColor: mapPalette.wallLine,
                }}
              >
                <div className="h-full w-1.5 absolute left-2 top-0" style={{ background: mapPalette.wallLine }} />
                {Array.from({ length: 14 }).map((_, i) => (
                  <div key={i} className="w-2.5 h-2.5 rounded-full" style={{ background: mapPalette.wallDot }} />
                ))}
              </div>

              {/* 右侧整条连续围墙 (厚度 2 格: x: 30..31) */}
              <div 
                className="absolute backdrop-blur-xs border-l border-r shadow-xs pointer-events-none z-10 flex flex-col justify-between py-4 items-center overflow-hidden"
                style={{
                  left: PADDING + (GRID_WIDTH - 2) * (CELL_SIZE + GAP),
                  top: PADDING + 2 * (CELL_SIZE + GAP),
                  width: 2 * CELL_SIZE + GAP,
                  height: (GRID_HEIGHT - 4) * (CELL_SIZE + GAP) - GAP,
                  background: mapPalette.wall,
                  borderColor: mapPalette.wallLine,
                }}
              >
                <div className="h-full w-1.5 absolute right-2 top-0" style={{ background: mapPalette.wallLine }} />
                {Array.from({ length: 14 }).map((_, i) => (
                  <div key={i} className="w-2.5 h-2.5 rounded-full" style={{ background: mapPalette.wallDot }} />
                ))}
              </div>

              {/* 底部左段连续围墙 (厚度 2 格: x: 0..13, y: 29..30) */}
              <div 
                className="absolute backdrop-blur-xs border shadow-xs pointer-events-none z-10 rounded-bl-2xl flex items-center justify-between px-6 overflow-hidden"
                style={{
                  left: PADDING,
                  top: PADDING + (GRID_HEIGHT - 2) * (CELL_SIZE + GAP),
                  width: 14 * CELL_SIZE + 13 * GAP,
                  height: 2 * CELL_SIZE + GAP,
                  background: mapPalette.wall,
                  borderColor: mapPalette.wallLine,
                }}
              >
                <div className="w-full h-1.5 absolute bottom-2 left-0" style={{ background: mapPalette.wallLine }} />
                {Array.from({ length: 6 }).map((_, i) => (
                  <div key={i} className="w-2.5 h-2.5 rounded-full" style={{ background: mapPalette.wallDot }} />
                ))}
              </div>

              {/* 底部大门基座连接道 (4x2 尺寸: x: 14..17, y: 29..30) */}
              <div 
                className="absolute border-t-2 border-b-2 pointer-events-none z-10 flex items-center justify-center shadow-inner"
                style={{
                  left: PADDING + 14 * (CELL_SIZE + GAP),
                  top: PADDING + (GRID_HEIGHT - 2) * (CELL_SIZE + GAP),
                  width: 4 * CELL_SIZE + 3 * GAP,
                  height: 2 * CELL_SIZE + GAP,
                  background: mapPalette.road,
                  borderColor: isDark ? 'rgba(251,191,36,0.45)' : 'rgba(252,211,77,0.6)',
                }}
              >
                <div className="w-full h-full flex flex-col justify-center items-center opacity-30">
                  <div className="w-full h-[1px]" style={{ background: mapPalette.gateLine }} />
                  <div className="w-full h-[1px] mt-3" style={{ background: mapPalette.gateLine }} />
                </div>
              </div>

              {/* 底部右段连续围墙 (厚度 2 格: x: 18..31, y: 29..30) */}
              <div 
                className="absolute backdrop-blur-xs border shadow-xs pointer-events-none z-10 rounded-br-2xl flex items-center justify-between px-6 overflow-hidden"
                style={{
                  left: PADDING + 18 * (CELL_SIZE + GAP),
                  top: PADDING + (GRID_HEIGHT - 2) * (CELL_SIZE + GAP),
                  width: 14 * CELL_SIZE + 13 * GAP,
                  height: 2 * CELL_SIZE + GAP,
                  background: mapPalette.wall,
                  borderColor: mapPalette.wallLine,
                }}
              >
                <div className="w-full h-1.5 absolute bottom-2 left-0" style={{ background: mapPalette.wallLine }} />
                {Array.from({ length: 6 }).map((_, i) => (
                  <div key={i} className="w-2.5 h-2.5 rounded-full" style={{ background: mapPalette.wallDot }} />
                ))}
              </div>

              {/* ================= 内部方格交互层 (仅在编辑建筑位置时，渐显半透明网格轮廓) ================= */}
              {placingState && Array.from({ length: GRID_WIDTH * GRID_HEIGHT }).map((_, i) => {
                const x = i % GRID_WIDTH;
                const y = Math.floor(i / GRID_WIDTH);
                if (x <= 1 || x >= GRID_WIDTH - 2 || y <= 1 || y >= GRID_HEIGHT - 2) return null;

                return (
                  <div
                    key={`inner_cell_${x}_${y}`}
                    onClick={() => handleCellClick(x, y)}
                    className={`absolute rounded-md cursor-pointer z-20 ${
                      isDark
                        ? 'border border-amber-300/30 bg-white/5 hover:bg-amber-200/15 hover:border-amber-300 hover:ring-2 hover:ring-amber-200/40'
                        : 'border border-border-default bg-white/20 hover:bg-selected hover:border-selected-border hover:ring-2 hover:ring-[color:var(--selected-border)]'
                    }`}
                    style={{
                      left: PADDING + x * (CELL_SIZE + GAP),
                      top: PADDING + y * (CELL_SIZE + GAP),
                      width: CELL_SIZE,
                      height: CELL_SIZE,
                    }}
                  />
                );
              })}

              {/* ================= 绘制已建造的建筑 ================= */}
              {displayBuildings.map(b => {
                const isGate = b.id === 'gate';
                const visual = getBuildingVisualStyle(b, isDark);
                
                return (
                  <div
                    key={b.id}
                    onPointerDown={(e) => handlePointerDown(e, b)}
                    onPointerMove={handlePointerMove}
                    onPointerUp={handlePointerUp}
                    onPointerLeave={handlePointerUp}
                    onPointerCancel={handlePointerUp}
                    onClick={() => {
                      if (wasLongPressed.current) {
                        wasLongPressed.current = false;
                        return;
                      }
                      if (placingState) return;
                      if (isEditMode) {
                        if (isGate) {
                          showToast('校园大门位于南侧围墙上，为特殊建筑不可修改', 'error');
                          return;
                        }
                        clearInfoToasts();
                        setEditingBuilding(b);
                      } else {
                        setSelectedBuilding(b);
                      }
                    }}
                    className={`absolute rounded-2xl shadow-xl flex items-center justify-center text-center font-bold ${isDark ? '' : visual.colorClass || b.color} backdrop-blur-sm pointer-events-auto cursor-pointer hover:ring-4 transition-all ${isDark ? 'hover:ring-amber-200/40' : 'hover:ring-white/70'} ${isGate ? 'z-20 border-4 shadow-2xl' : 'z-10 border-4'}`}
                    style={{
                      left: PADDING + b.x * (CELL_SIZE + GAP),
                      top: PADDING + b.y * (CELL_SIZE + GAP),
                      width: b.width * CELL_SIZE + (b.width - 1) * GAP, 
                      height: b.height * CELL_SIZE + (b.height - 1) * GAP,
                      ...(isDark
                        ? {
                            backgroundColor: visual.backgroundColor,
                            borderColor: visual.borderColor,
                            boxShadow: '0 10px 28px rgba(0,0,0,0.45), inset 0 1px 0 rgba(255,255,255,0.06)',
                          }
                        : {}),
                    }}
                  >
                    <div 
                      className="px-2 py-1 font-black tracking-wide pointer-events-auto select-none max-w-[calc(100%-8px)] overflow-hidden flex items-center justify-center text-center"
                      style={{ color: visual.textColor }}
                    >
                      {b.name.length > b.width * 2 ? (
                        <marquee scrollamount="3" className="whitespace-nowrap text-3xl font-black">{b.name}</marquee>
                      ) : (
                        <span className="whitespace-nowrap text-3xl font-black">{b.name}</span>
                      )}
                    </div>

                    {/* 活动中醒目标签 (建筑左上角) */}
                    {(() => {
                      const hasActiveEvent = (b.events || []).some(e => isTimestampInRange(nowTs, e.startTime, e.endTime));
                      if (!hasActiveEvent) return null;
                      return (
                        <div className={`absolute -top-5 -left-5 bg-gradient-to-r from-amber-500 via-orange-500 to-rose-500 text-white text-2xl font-black px-4 py-1.5 rounded-2xl flex items-center gap-2 border-4 shadow-2xl z-30 pointer-events-none ${
                          isDark ? 'border-amber-200/80' : 'border-white'
                        }`}>
                          <span className="relative flex h-3.5 w-3.5 shrink-0">
                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-white opacity-80"></span>
                            <span className="relative inline-flex rounded-full h-3.5 w-3.5 bg-yellow-300"></span>
                          </span>
                          <span className="tracking-wider whitespace-nowrap drop-shadow-sm">活动中</span>
                        </div>
                      );
                    })()}

                    {/* 人物在场角标 (放大一倍，清晰可见) */}
                    {(() => {
                      const charCount = characters.filter(c => c.location === b.name).length;
                      return charCount > 0 ? (
                        <div className={`absolute -top-4 -right-4 bg-rose-500 text-white text-base font-black w-10 h-10 rounded-full flex items-center justify-center border-4 shadow-lg z-30 pointer-events-none ${
                          isDark ? 'border-slate-800' : 'border-white'
                        }`}>
                          {charCount}
                        </div>
                      ) : null;
                    })()}
                  </div>
                );
              })}
              
              {/* ================= 绘制预览建筑 ================= */}
              {placingState && placingState.previewX !== null && placingState.previewY !== null && (() => {
                const previewVisual = getBuildingVisualStyle(placingState.building, isDark);
                return (
                <div
                  className={`absolute rounded-2xl shadow-2xl flex items-center justify-center text-center font-bold ${isDark ? '' : placingState.building.color} backdrop-blur-md pointer-events-none z-40 opacity-85 animate-floating border-4 border-selected-border ring-4 ring-[color:var(--selected-border)]`}
                  style={{
                    left: PADDING + placingState.previewX * (CELL_SIZE + GAP),
                    top: PADDING + placingState.previewY * (CELL_SIZE + GAP),
                    width: placingState.building.width * CELL_SIZE + (placingState.building.width - 1) * GAP,
                    height: placingState.building.height * CELL_SIZE + (placingState.building.height - 1) * GAP,
                    ...(isDark
                      ? {
                          backgroundColor: previewVisual.backgroundColor,
                          borderColor: 'var(--selected-border)',
                        }
                      : {}),
                  }}
                >
                  <span 
                    className="px-2 py-1 text-3xl font-black tracking-wide select-none"
                    style={{ color: previewVisual.textColor }}
                  >
                    {placingState.building.name}
                  </span>
                </div>
                );
              })()}

              {isDark && (
                <div className="absolute inset-0 pointer-events-none overflow-hidden z-[25]">
                  {MAP_STARS.map((star, index) => (
                    <span
                      key={`star-${index}`}
                      className="absolute rounded-full"
                      style={{
                        left: star.left,
                        top: star.top,
                        width: star.size,
                        height: star.size,
                        background: star.glow ? 'rgba(255, 248, 220, 0.95)' : 'rgba(255, 255, 255, 0.9)',
                        boxShadow: star.glow
                          ? '0 0 8px 2px rgba(253, 224, 71, 0.7)'
                          : '0 0 4px 1px rgba(255, 255, 255, 0.55)',
                        animation: `star-twinkle ${star.duration} ease-in-out infinite`,
                        animationDelay: star.delay,
                      }}
                    />
                  ))}
                </div>
              )}

              {/* ================= 飘动的半透明浮云层 (6朵大小各异、错落分布，其中2朵从右向左飘) ================= */}
              <div className={`absolute inset-0 pointer-events-none overflow-hidden z-30 ${isDark ? 'opacity-25' : 'opacity-70'}`}>
                {/* 云朵 1: 小型轻盈云 (从左向右飘) */}
                <div 
                  className="absolute"
                  style={{
                    top: '8%',
                    left: '0px',
                    animation: 'cloud-drift-lr 32s linear infinite',
                    animationDelay: '-6s'
                  }}
                >
                  <div 
                    className="w-48 h-16 bg-white/75 rounded-full blur-[1px] shadow-sm relative"
                    style={{ animation: 'cloud-gentle-bob 5s ease-in-out infinite' }}
                  >
                    <div className="absolute -top-6 left-8 w-20 h-20 bg-white/80 rounded-full" />
                    <div className="absolute -top-4 left-20 w-16 h-16 bg-white/75 rounded-full" />
                  </div>
                </div>

                {/* 云朵 2: 特大宏伟云 (从左向右飘) */}
                <div 
                  className="absolute"
                  style={{
                    top: '24%',
                    left: '0px',
                    animation: 'cloud-drift-lr 52s linear infinite',
                    animationDelay: '-32s'
                  }}
                >
                  <div 
                    className="w-96 h-28 bg-white/65 rounded-full blur-[2px] shadow-md relative"
                    style={{ animation: 'cloud-gentle-bob 8s ease-in-out infinite' }}
                  >
                    <div className="absolute -top-14 left-14 w-40 h-40 bg-white/70 rounded-full" />
                    <div className="absolute -top-10 left-48 w-32 h-32 bg-white/65 rounded-full" />
                    <div className="absolute -top-6 left-28 w-24 h-24 bg-white/60 rounded-full" />
                  </div>
                </div>

                {/* 云朵 3: 中型灵动云 (从右向左逆向飘 #1) */}
                <div 
                  className="absolute"
                  style={{
                    top: '41%',
                    left: '0px',
                    animation: 'cloud-drift-rl 38s linear infinite',
                    animationDelay: '-14s'
                  }}
                >
                  <div 
                    className="w-60 h-20 bg-white/70 rounded-full blur-[1.5px] shadow-sm relative"
                    style={{ animation: 'cloud-gentle-bob 6s ease-in-out infinite' }}
                  >
                    <div className="absolute -top-8 left-12 w-24 h-24 bg-white/75 rounded-full" />
                    <div className="absolute -top-5 left-32 w-18 h-18 bg-white/70 rounded-full" />
                  </div>
                </div>

                {/* 云朵 4: 大型绵密云 (从右向左逆向飘 #2) */}
                <div 
                  className="absolute"
                  style={{
                    top: '59%',
                    left: '0px',
                    animation: 'cloud-drift-rl 48s linear infinite',
                    animationDelay: '-27s'
                  }}
                >
                  <div 
                    className="w-80 h-26 bg-white/60 rounded-full blur-[2px] shadow-sm relative"
                    style={{ animation: 'cloud-gentle-bob 9s ease-in-out infinite' }}
                  >
                    <div className="absolute -top-12 left-16 w-36 h-36 bg-white/65 rounded-full" />
                    <div className="absolute -top-8 left-44 w-28 h-28 bg-white/60 rounded-full" />
                  </div>
                </div>

                {/* 云朵 5: 中小舒缓云 (从左向右飘) */}
                <div 
                  className="absolute"
                  style={{
                    top: '75%',
                    left: '0px',
                    animation: 'cloud-drift-lr 36s linear infinite',
                    animationDelay: '-19s'
                  }}
                >
                  <div 
                    className="w-52 h-18 bg-white/65 rounded-full blur-[1.5px] shadow-sm relative"
                    style={{ animation: 'cloud-gentle-bob 7s ease-in-out infinite' }}
                  >
                    <div className="absolute -top-7 left-10 w-22 h-22 bg-white/70 rounded-full" />
                    <div className="absolute -top-4 left-26 w-16 h-16 bg-white/65 rounded-full" />
                  </div>
                </div>

                {/* 云朵 6: 微型轻巧云 (从左向右飘) */}
                <div 
                  className="absolute"
                  style={{
                    top: '90%',
                    left: '0px',
                    animation: 'cloud-drift-lr 26s linear infinite',
                    animationDelay: '-11s'
                  }}
                >
                  <div 
                    className="w-36 h-12 bg-white/70 rounded-full blur-[1px] shadow-xs relative"
                    style={{ animation: 'cloud-gentle-bob 4.5s ease-in-out infinite' }}
                  >
                    <div className="absolute -top-5 left-6 w-14 h-14 bg-white/75 rounded-full" />
                    <div className="absolute -top-3 left-16 w-10 h-10 bg-white/70 rounded-full" />
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* ================= 建造弹窗层 ================= */}
      <BottomSheetModal 
        isOpen={showBuildModal} 
        onClose={() => setShowBuildModal(false)}
        className="z-60"
      >
        <div 
          className="flex-1 overflow-y-auto overflow-x-hidden hide-scrollbar pb-12 pt-8 px-5"
          {...buildScrollProps}
          ref={buildScrollProps.ref}
        >
          <h2 className="text-xl font-bold text-text-primary mb-6 flex items-center gap-2">
            <Hammer className="w-5 h-5 text-[color:var(--action-text)]" />
            规划新建筑
          </h2>
          
          <div className="space-y-4">
            <div>
              <label className="text-xs font-bold text-text-secondary mb-2 block">建筑名称</label>
              <input 
                type="text" 
                value={buildForm.name}
                onChange={e => setBuildForm({ ...buildForm, name: e.target.value })}
                placeholder="例如：实验楼、游泳馆、天文台"
                className="w-full rounded-xl py-3 px-4 theme-field"
              />
            </div>
            
            <div className="flex gap-4">
              <SizeStepper
                label="宽度 (方格数 1-6)"
                value={buildForm.width}
                min={1}
                max={6}
                onChange={width => setBuildForm({ ...buildForm, width })}
              />
              <SizeStepper
                label="长度 (方格数 1-6)"
                value={buildForm.height}
                min={1}
                max={6}
                onChange={height => setBuildForm({ ...buildForm, height })}
              />
            </div>

            <div>
              <label className="text-xs font-bold text-text-secondary mb-2 block">建筑简介 (选填)</label>
              <textarea 
                value={buildForm.description}
                onChange={e => setBuildForm({ ...buildForm, description: e.target.value })}
                placeholder="添加一段关于该建筑的描述..."
                className="w-full rounded-xl py-3 px-4 theme-field min-h-[80px] resize-none"
              />
            </div>

            <div>
              <label className="text-xs font-bold text-text-secondary mb-2 block">建筑分类与颜色</label>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                {BUILDING_COLOR_PALETTES.map(palette => {
                  const isSelected = buildForm.color === palette.colorClass;
                  return (
                    <button
                      key={palette.id}
                      type="button"
                      onClick={() => setBuildForm({ ...buildForm, color: palette.colorClass })}
                      className={`flex items-center gap-2.5 p-2.5 rounded-xl border-2 transition-all cursor-pointer text-left ${
                        isSelected
                          ? 'theme-selected ring-2 ring-[color:var(--selected-border)]'
                          : 'border-border-default/60 hover:border-selected-border bg-surface-solid'
                      }`}
                    >
                      <div 
                        className="w-6 h-6 rounded-lg shrink-0 shadow-xs border"
                        style={{
                          backgroundColor: isDark ? palette.darkBg : palette.bg,
                          borderColor: isDark ? palette.darkBorder : palette.border,
                        }}
                      />
                      <div className="flex-1 min-w-0">
                        <div className={`text-xs font-bold leading-none truncate ${isSelected ? 'text-selected-text' : 'text-text-primary'}`}>{palette.name}</div>
                        <div className={`text-[10px] mt-0.5 truncate ${isSelected ? 'text-selected-text/80' : 'text-text-secondary'}`}>{palette.category}</div>
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>

            <button 
              onClick={handleStartBuild}
              disabled={!buildForm.name.trim()}
              className="w-full py-4 mt-6 accent-btn font-bold rounded-xl shadow-sm transition-all active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed text-lg cursor-pointer"
            >
              确认规划，选择位置
            </button>
          </div>
        </div>
      </BottomSheetModal>

      {/* ================= 建筑详情弹窗 ================= */}
      {selectedBuilding && (
        <BuildingDetailsModal 
          building={selectedBuilding}
          onBuildingsChange={onBuildingsChange}
          characters={characters}
          buildings={buildings}
          rules={rules}
          nowTs={nowTs}
          onClose={() => setSelectedBuilding(null)}
          onCharacterClick={onCharacterClick}
        />
      )}

      {/* ================= 建筑编辑弹窗 ================= */}
      <BottomSheetModal 
        isOpen={!!editingBuilding} 
        onClose={() => setEditingBuilding(null)}
        className="z-60"
      >
        {editingBuilding && (
          <div 
            className="flex-1 overflow-y-auto overflow-x-hidden hide-scrollbar pb-12 pt-8 px-5"
            {...editScrollProps}
            ref={editScrollProps.ref}
          >
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-xl font-bold text-text-primary flex items-center gap-2">
                <Pencil className="w-5 h-5 text-[color:var(--action-text)]" />
                编辑建筑
              </h2>
            </div>
            
            <div className="space-y-4">
              <div>
                <label className="text-xs font-bold text-text-secondary mb-2 block">建筑名称</label>
                <input 
                  type="text" 
                  value={editingBuilding.name}
                  onChange={e => setEditingBuilding({ ...editingBuilding, name: e.target.value })}
                  className="w-full rounded-xl py-3 px-4 theme-field"
                />
              </div>
              
              <div className="flex gap-4">
                <SizeStepper
                  label="宽度 (1-6)"
                  value={editingBuilding.width}
                  min={1}
                  max={6}
                  onChange={width => setEditingBuilding({ ...editingBuilding, width })}
                />
                <SizeStepper
                  label="长度 (1-6)"
                  value={editingBuilding.height}
                  min={1}
                  max={6}
                  onChange={height => setEditingBuilding({ ...editingBuilding, height })}
                />
              </div>

              <div>
                <label className="text-xs font-bold text-text-secondary mb-2 block">建筑简介</label>
                <textarea 
                  value={editingBuilding.description || ''}
                  onChange={e => setEditingBuilding({ ...editingBuilding, description: e.target.value })}
                  placeholder="输入建筑简介..."
                  className="w-full rounded-xl py-3 px-4 theme-field min-h-[80px] resize-none"
                />
              </div>

              <div>
                <label className="text-xs font-bold text-text-secondary mb-2 block">建筑分类与颜色</label>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                  {BUILDING_COLOR_PALETTES.map(palette => {
                    const isSelected = editingBuilding.color === palette.colorClass;
                    return (
                      <button
                        key={palette.id}
                        type="button"
                        onClick={() => setEditingBuilding({ ...editingBuilding, color: palette.colorClass })}
                        className={`flex items-center gap-2.5 p-2.5 rounded-xl border-2 transition-all cursor-pointer text-left ${
                          isSelected
                            ? 'theme-selected ring-2 ring-[color:var(--selected-border)]'
                            : 'border-border-default/60 hover:border-selected-border bg-surface-solid'
                        }`}
                      >
                        <div 
                          className="w-6 h-6 rounded-lg shrink-0 shadow-xs border"
                          style={{
                            backgroundColor: isDark ? palette.darkBg : palette.bg,
                            borderColor: isDark ? palette.darkBorder : palette.border,
                          }}
                        />
                        <div className="flex-1 min-w-0">
                          <div className={`text-xs font-bold leading-none truncate ${isSelected ? 'text-selected-text' : 'text-text-primary'}`}>{palette.name}</div>
                          <div className={`text-[10px] mt-0.5 truncate ${isSelected ? 'text-selected-text/80' : 'text-text-secondary'}`}>{palette.category}</div>
                        </div>
                      </button>
                    );
                  })}
                </div>
              </div>
              
              <div className="flex flex-col gap-3 mt-6">
                <div className="flex gap-3">
                  <button 
                    onClick={handleStartMove}
                    className={`flex-1 py-4 font-bold rounded-xl shadow-sm transition-all active:scale-95 text-base flex items-center justify-center gap-2 cursor-pointer border ${
                      isDark
                        ? 'bg-sky-500/20 text-sky-300 border-sky-400/50 hover:bg-sky-500/30'
                        : 'bg-sky-50 text-sky-600 border-sky-200 hover:bg-sky-100'
                    }`}
                  >
                    <Move className="w-5 h-5" /> 改变位置
                  </button>

                  <button 
                    onClick={() => {
                      if (editingBuilding) {
                        onBuildingsChange(buildings.filter(b => b.id !== editingBuilding.id));
                        setEditingBuilding(null);
                        showToast('已删除建筑', 'success');
                      }
                    }}
                    className={`px-6 py-4 font-bold rounded-xl shadow-sm transition-all active:scale-95 text-base flex items-center justify-center gap-2 cursor-pointer border ${
                      isDark
                        ? 'bg-rose-500/20 text-rose-300 border-rose-400/45 hover:bg-rose-500/30'
                        : 'bg-red-50 text-red-500 border-red-100 hover:bg-red-100'
                    }`}
                  >
                    <Trash2 className="w-5 h-5" /> 删除
                  </button>
                </div>

                <button 
                  onClick={() => {
                    if (editingBuilding.name.trim() === '') return;
                    
                    // 检查是否碰撞围墙（2格厚度）
                    const x = editingBuilding.x;
                    const y = editingBuilding.y;
                    let hitsWall = false;
                    for (let i = x; i < x + editingBuilding.width; i++) {
                      for (let j = y; j < y + editingBuilding.height; j++) {
                        if (i <= 1 || i >= GRID_WIDTH - 2 || j <= 1 || j >= GRID_HEIGHT - 2) hitsWall = true;
                      }
                    }
                    
                    if (hitsWall) {
                      showToast('无法在2格围墙上或校园外建造！', 'error');
                      return;
                    }

                    // 检查是否重叠
                    const isOverlap = buildings.some(b => 
                      b.id !== editingBuilding.id && 
                      x < b.x + b.width && 
                      x + editingBuilding.width > b.x && 
                      y < b.y + b.height && 
                      y + editingBuilding.height > b.y
                    );

                    if (isOverlap) {
                      showToast('该位置已有建筑，无法放置！', 'error');
                      return;
                    }

                    onBuildingsChange(buildings.map(b => b.id === editingBuilding.id ? editingBuilding : b));
                    setEditingBuilding(null);
                    showToast('建筑已更新', 'success');
                  }}
                  className="w-full py-4 accent-btn font-bold rounded-xl shadow-sm transition-all active:scale-95 text-base flex items-center justify-center gap-2 cursor-pointer"
                >
                  <Pencil className="w-5 h-5" /> 保存修改
                </button>
              </div>
            </div>
          </div>
        )}
      </BottomSheetModal>
    </FullScreenModal>
  );
};
