import { useCallback, useEffect, useState } from 'react';
import { loadPhoneCloseMode, PhoneCloseMode, savePhoneCloseMode } from '../utils/closeModeStore';

let snapshot: PhoneCloseMode = loadPhoneCloseMode();
const listeners = new Set<() => void>();

function emit() {
  listeners.forEach(listener => listener());
}

export function setPhoneCloseMode(mode: PhoneCloseMode) {
  snapshot = mode;
  savePhoneCloseMode(mode);
  emit();
}

export function usePhoneCloseMode() {
  const [mode, setMode] = useState<PhoneCloseMode>(snapshot);

  useEffect(() => {
    const listener = () => setMode(snapshot);
    listeners.add(listener);
    return () => {
      listeners.delete(listener);
    };
  }, []);

  const changeMode = useCallback((next: PhoneCloseMode) => {
    setPhoneCloseMode(next);
  }, []);

  return {
    closeMode: mode,
    setCloseMode: changeMode,
    closeOnOutside: mode === 'outside',
  };
}
